-- UTF-8 / Persian-safe SQL dump
-- Compatible with SQLite

PRAGMA foreign_keys = ON;

BEGIN TRANSACTION;

CREATE TABLE IF NOT EXISTS chapters (
    id INTEGER PRIMARY KEY,
    title TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS articles (
    id INTEGER PRIMARY KEY,
    chapter_id INTEGER NOT NULL,
    article_number INTEGER NOT NULL UNIQUE,
    title TEXT NOT NULL,
    text TEXT NOT NULL,
    interpretation TEXT,
    FOREIGN KEY (chapter_id) REFERENCES chapters(id)
);

CREATE TABLE IF NOT EXISTS article_relations (
    article_id INTEGER NOT NULL,
    related_article_id INTEGER NOT NULL,
    PRIMARY KEY (article_id, related_article_id),
    FOREIGN KEY (article_id) REFERENCES articles(id),
    FOREIGN KEY (related_article_id) REFERENCES articles(id)
);

INSERT INTO chapters (id, title) VALUES (1, 'تعاريف و مفاهيم');
INSERT INTO chapters (id, title) VALUES (2, 'تاييدات  و تعهدات پيمانكار');
INSERT INTO chapters (id, title) VALUES (3, 'تعهدات و اختيارات كارفرما');
INSERT INTO chapters (id, title) VALUES (4, 'تضمين ، پرداخت ، تحويل كار');
INSERT INTO chapters (id, title) VALUES (5, 'حوادث قهري ، فسخ ، ختم ، تعليق ، هزينه تسريع ، خسارت تاخير ، تسويه حساب ، حل اختلاف');

INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (1, 1, 1, 'پيمان', 'پيمان مجموعه اسناد و مداركي است كه در ماده 2 موافقت نامه پيمان درج شده است .', 'این ماده «پیمان» را تعریف می‌کند: مجموعه کامل اسناد و مدارکی که در ماده ۲ موافقت‌نامه فهرست شده‌اند.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (2, 1, 2, 'موافقت نامه', 'موافقت نامه سندي است كه مشخصات اصلي پيمان ، مانند مشخصات دو طرف ، موضوع ، مبلغ و مدت پيمان در آن بيان شده است .', 'بخش موافقت نامه پیمان از سوی سازمان برنامه و بودجه تهیه و تنظیم شده است و دارای 7 ماده می باشد.
در واقع متن موافقت نامه، چکیده بسیار کوچکی از پیمان است  که جزئیات آن در سایر اسناد و مدارک پیمان مانند شرایط عمومی، شرایط خصوصی و... ذکر می شود.
 موافقت نامه پایه و اساس پیمان را تشکیل می دهد.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (3, 1, 3, 'شرايط عمومي', 'شرايط عمومي ، مفاد همين متن است كه شرايط عمومي حاكم بر پيمان را تعيين ميكند .', 'شرایط عمومی مثل قانون، حاکم بر کلیه پیمانهاست. تمام ماده های آن دست نخورده و بدون تغییر می ماند و دو طرف پیمان نمی توانند ان را تغییر دهند.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (4, 1, 4, 'شرايط خصوصي', 'شرايط خصوصي، شرايط خاصي است كه به منظور تكميل شرايط عمومي ، براي اين پيمان ، با توجه به وضعيت و ماهيت آن ، تنظيم شده است . موارد درج شده در شرايط خصوصي ، هيچ گاه نمي تواند مواد شرايط عمومي را نقض كند .', 'مواد مربوط به شرایط خصوصی به نحوی تنظیم شود که پاسخگوی نیاز کارهای مختلف باشد. از این رو مواد شرایط خصوصی بر حسب نیاز هر کار، با رعایت تمام مقررات پر می شود. تمام صفحات شرایط خصوصی باید توسط نمایندگان مجاز دو طرف پیمان امضا و مهر گردند.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (5, 1, 5, 'برنامه زماني اجراي كار', 'الف) برنامه زماني كلي : برنامه اي است كه در آن، زمانبندي كلي كار هاي مورد پيمان بر حسب ماه ، منعكس گشته و  در اسناد و مدارك پيمان درج شده است .
ب) برنامه زماني تفصيلي : برنامه اي است كه زمان بندي فعاليت هاي مختلف كار هاي موضوع پيمان ، به تفصيل و در چارچوب برنامه زماني كلي ، در آن آمده است .', 'برنامه زمانبندی کلی: همان مدت اولیه پیمان است که در برنامه زمانبندی کلی کارهای مورد پیمان برحسب ماه، منعکس گشته و در اسناد و مدارک پیمان درج می شود. در واقع برنامه زمانی کلی به صورت ماهیانه فعالیت های گونانگون تا تا پایان پروژه و تحویل موقت را مشخص می کند.
بر نامه زمانبندی کلی توسط مشاور یا کارفرما تهیه می شود.

برنامه زمانبندی تفصیلی: در چارچوب برنامه زمانبندی کلی تنظیم می شود و فعالیت های مختلف مورد اشاره در برنامه زمانی کلی را با تفصیل و ارائه جزئیات بیشتر تهیه می شود.
برنامه زمانبندی تفصیلی توسط پیمانکار تهیه می شود.  رعایت برنامه زمانی اجرای کار برای پیمانکار دارای اهمیت ویژه ای است، زیرا چنانچه پیمانکار در هریک از مراحل برنامه زمانی تاخیر غیر مجاز زیادی داشته باشد ممکن است مطابق جزهای 2 تا7 بند الف ماده 46 شرایط عمومی پیمان، کارفرما به فسخ پیمان مبادرت کند');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (6, 1, 6, 'كارفرما', 'كارفرما ، شخص حقوقي است كه يك سوي امضاء  كننده پيمان است و عمليات موضوع پيمان را بر اساس اسناد  و مدارك پيمان ، به پيمانكار واگذار كرده است . نمايندگان و جانشين هاي قانوني كارفرما ، در حكم كارفرما 
مي باشد .', 'در پیمان، کارفرما به عنوان شخص حقوقی در مقابل پیمانکار به عنوان شخص حقیقی یا حقوقی تعهدات متقابل برابر هم دارند که مورد قبول دو طرف قرار گرفته و پیمان را امضا می کنند');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (7, 1, 7, 'پيمانكار', 'پيمانكار ، شخص حقيقي يا حقوقي است كه سوي ديگر امضاء كننده پيمان است و اجراي موضوع پيمان را بر اساس اسناد و مدارك پيمان ، به عهده گرفته است . نمايندگان و جانشين هاي قانوني پيمانكار ، در حكم پيمانكار مي باشد .', 'نمایندگان پیمانکار در حین عملیات اجرایی پیمان:
1- کارکنان پیمانکار 
2- پیمانکاران جز
3- رئیس (یا سرپرست) کارگاه');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (8, 1, 8, 'مدير طرح', 'مدير طرح ، شخص حقوقي است كه به منظور مديريت اجراي كار ، در چارچوب اختيارات تعيين شده در اسناد و مدارك پيمان ، از سوي كارفرما به پيمانكار معرفي مي شود .', 'مدیر طرح را بعد از مثلث کارفرما، مهندسین مشاور و پیمانکار، عامل چهارم پیمان نیز می گویند. وجود مدیر طرح در پیمان به اختیار کارفرما است.
بر اساس ماده 31 شرایط عمومی پیمان کارفرما می تواند قسمتی از اختیارات خود را به شخص حقوقی، که مدیر طرح نامیده می شود واگذار کند.
مدیر طرح نمی تواند در مسائلی که بار مالی دارند ورود کند.
در بخشنامه 75.54/2983 105/8 مورخ 1380/06/13 تحت عنوان شرح خدمات مدیر طرح، وظایف مدیر طرح ابلاغ شده است 1- تمام تاییدهای که بر اساس قانون محاسبات عمومی باید به امضای بالاترین مقام دستگاه اجرایی باشد.
2- قبول تضمین ها و دستور تمدید، ضبط و واریز آن ها حسب ماده 34 شرایط عمومی پیمان
3- تصویب تغییر مبلغ پیمان
4- تصویب تغییر مدت پیمان
5- تصویب قیمت های جدید
6- تصویب تحویل موقت و تحویل قطعی7- تصمیم در مورد تعلیق، خاتمه یا فسخ پیمان
8-تصویب صورت وضعیت قطعی و صورت حساب نهایی');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (9, 1, 9, 'مهندس مشاور ، مهندس ناظر', 'الف) مهندس مشاور ، شخص حقيقي يا حقوقي است كه براي نظارت بر اجراي كار ، در چارچوب اختيارات تعيين شده در اسناد و مدارك پيمان ، از سوي كارفرما به پيمانكار معرفي مي شود .
ب) مهندس ناظر ، نماينده مقيم مهندس مشاور در كارگاه است و در چارچوب اختيارات تعيين شده در اسناد و مدارك پيمان به پيمانكار معرفي ميشود .', 'اگر چه مهندس مشاور جزو طرفین پیمان نیست لکن اساساً تهیه و اجرای طرح های عمرانی از طریق مثلث کارفرما، پیمانکار و مهندس مشاور انجام می شود.
وظایف مهندس مشاور در طرح های عمرانی شامل: مطالعات، طراحی و نظارت می باشد.
وجود مهندس مشاور در پیمان، برخلاف مدیر طرح، الزامی است و از لوازم و ضروریات پیمان محسوب می شودوظایف و اختیارات مهندس ناظر:
1- نظارت و مراقبت دقیق اجرای کار
2-  آزمایش کردن مصالح و تجهیزاتی که باید به مصرف برسد
3- صدور دستور رفع نقص کارها به پیمانکار
4- صدور دستور مبنی بر تعمیر یا تعویض و یا تغییر ماشین آلات معیوب پیمانکار
5- مداخله نکردن مهندس ناظر در کاهش تعهدات پیمانکار.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (10, 1, 10, 'رئيس كارگاه', 'رئيس كارگاه، شخصي حقيقي داراي تخصص و تجربه لازم است كه پيمانكار ، او را به مهندس مشاور معرفي 
مي كند تا اجراي موضوع پيمان در كارگاه را سرپرستي كند .', 'رئیس کارگاه به عنوان نماینده پیمانکار و مهندس ناظر به عنوان نماینده مهندس مشاور، هر دو در کارگاه حضور فیزیکی دارند و مسئولیت های محوله را انجام می دهند.از وظایف رییس کارگاه این است که تمام وقت در کارگاه باشد. اگر معلوم شود سرپرست کارگاه واجد صلاحیت نباشد، مهندس مشاور از پیمانکار درخواست می کند طی حداکثر یک ماه تعویض رئیس کارگاه را می کند. همچنین در صورتی که پیمانکار قصد تغییر رئیس کارگاه را داشته باشد، می بایست از قبل موضوع را به اطلاع مهندس مشاور برساند.برابر جز 8 بند الف ماده 46 شریط عمومی پیمان « بدون سرپرست گذاشتن کارگاه بدون اجازه کارفرما به مدت بیش از 15 روز» می تواند از موارد فسخ پیمان باشد.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (11, 1, 11, 'پيمانكار جزء', 'پيمانكار جزء، شخص حقيقي يا حقوقي است كه تخصص در كار هاي اجرايي دارد و پيمانكار براي اجراي بخشي از عمليات موضوع پيمان ، با او قرارداد مي بندد.', 'چون موضوع پیمان وسیع و بزرگ است و هر پیمانکار ادر به اجرای تمام بخش های پیمان نیست و جهت تسریع در انجام پروژه، کارفرما این حق پیمانکار را به رسمیت می شناسد که او بتواند بخشی از کار ها را به پیمانکار جز واگذار کند.پیمانکار طرف اصلی کارفرما محسوب می شود و اصولا و به طور کلی حق ندارد موضوع پیمان را به ثالث واگذار کند.پیمانکار جز باید تخصص لازم در انجام کارهای اجرایی را داشته باشد.
پیمانکار باید صلاحیت انجام از آن بخش از پیمان که به او واگذار می شود را داشته باشد.
پیمانکار اصلی باید با پیمانکار جز راجع به انجام قسمتی از موضوع پیمان، قرارداد داشته باشد.
بر اساس بند ب ماده 24 شرایط عمومی پیمان، پیمانکار اصلی در قراردادی که با پبمانکار جز می بنند، باید کارفرما را داور طرفین خود قرار دهد تا در صورت بروز اختلاف بین او و پیمانکار جز، کارفرما حق داوری و فصل خصومت بین آنها را داشته باشد.
پیمانکار جز می تواند شخص حقیقی یا حقوقی باشد.
پیمانکار اصلی انتخاب پیمانکار جز را به صورت مکتوب به اصلاع مهندس مشاور و کارفرما می رساند.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (12, 1, 12, 'كار ، كارگاه ، تجهيز ، و برچيدن كارگاه', 'الف) كار ، عبارت است از مجموعه عمليات ، خدمات يا اقدامات مورد نياز ، براي آغاز كردن ، انجام و پايان دادن عمليات موضوع پيمان است و شامل كارهاي دايمي است كه باقي خواهد ماند و به عنوان موضوع پيمان تحويل كارفرما مي گردد ، و كار هاي موقتي است كه به منظور اجرا  و نگه داري موضوع پيمان انجام مي شود .
ب) كارگاه ، محل يا محل هايي است كه عمليات موضوع پيمان در آن اجرا مي شود يا به منظور اجراي پيمان ، با اجازه ي كارفرما از آن استفاده مي كنند . كارگاهها يا كارخانه هاي توليدي خارج از محلها و زمين هاي تحويلي كارفرما ، كه به منظور ساخت تجهيزات يا قطعاتي كه در كار نصب خواهد شد مورد استفاده قرار مي گيرد
ج) تجهيز كارگاه ، عبارت از عمليات ، اقدام ها و تداركاتي است كه بادي به صورت موقت براي دوره اجرا انجام شود ، تا آغاز كردن و انجام دادن عمليات موضوع پيمان ، طبق اسناد و مدارك پيمان ، ميسر شود .
د) برچيدن كارگاه ، عبارت است از جمع آوري مصالح ، تجهيزات ، تاسيسات و ساختمان هاي موقت ، خارج كردن مواد زايد ، مصالح ، تجهيزات ، ماشين آلات و ديگر تداركات پيمانكار از كارگاه و تسطيح و تميز كردن محل هاي تحويلي كارفرما مي باشد .', 'کار دو بخش دارد: کارهای دائمی که ماندگار هستند و کارها موقتی که جهت اجرا و نگهداری کارهای دائمی ضروری هستند.بر اساس بند الف ماده 20 شرایط عومی پیمان «پیمانکار موظف است که پس از تحویل کارگاه با توجه به مدت تعیین شده برای تجهیز، طرح جانمایی تجهیز کارگاه را تهیه و به تایید مهندس مشاور برساند تا مبنای تجهیز کارگاه قرار گیرد. همچنین مدت تجهیز کارکاه در بند ج ماده 4 موافقتت نامه ذکر می شود.»بر اساس جز 3 بند الف ماده 46 شرایط عمومی پیمان در صورت تاخیر در تجهیز کارگاه برای شروع عملیات موضوع پیمان، بیش از مدت نعیین شده در بند ج ماده 4 موافقت نامه، کارفرما می تواند قرارداد را فسخ کند.» بر اساس جز 3 بند الف ماده 46 شرایط عمومی پیمان در صورتی که بعد از تحویل کارگاه، کارفرما بخشی از پیش پرداخت را به پیمانکار پرداخت نکرده باشد، نمی تواند نسبت به فسخ پیمان اقدام کند.

همچنین با توجه به جز 9 بند الف ماده 30 شرایط عمومی پیمان « هرگاه کارفرما نتواند تعهدات مالی خود را در موعدهای درج شده در اسناد و مدارک پیمان انجام دهد» این امر موجب افزایش مدت اجرای کار شده و پیمانکار برای حفظ حقوق خود تمدید مدت پیمان را از طریق مهندس مشاور از کارفرما درخواست می کند. چرا که کارسازی پیش پرداخت از جانب کارفرما به پیمانکار یکی از تکالیف وی مندرج در ماده 36 شرایط عمومی پیمان است.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (13, 1, 13, 'مصالح ، تجهيزات، مصالح و تجهيزات پاي كار ، ماشين آلات و ابزار ، تاسيسات و ساختمان هاي موقت ، وسايل', 'الف) مصالح، عبارت است از مواد ، اجناس و كالاها يي كه در عمليات موضوع پيمان مصرف يا نصب شده و در كار باقي مي ماند .
ب) تجهيزات، عبارت از دستگاهها و ماشين آلاتي است كه در عمليات موضوع پيمان و در كار باقي مي ماند .
ج) مصالح و تجهيزات پاي كار، عبارت از مصالح و تجهيزاتي كه پيمانكار ، با توجه به اسناد و مدارك پيمان براي اجراي موضوع پيمان ، تهيه كرده و در محلي يا محلهايي از كارگاه كه در طرح جانمايي تجهيز كارگاه به عنوان انبار كارگاه يا محل انباشت مصالح تعيين گرديده است ، نگه داري و حفاظت مي كند . مصالح و تجهيزات موجود در محل مصرف يا نصب نيز مصالح و تجهيزات پاي كار ناميده مي شود .
تبصره – قطعات پيش ساخته و تجهيزاتي كه در اجراي موضوع پيمان ، با اجازه ي كارفرما و زير نظر مهندسين مشاور ، در كارگاه ها ويا در كارخانه هاي توليدي خارج از كارگاه ساخته شود نيز در حكم مصالح و تجهيزات پاي كار به شمار مي رود .
د) ماشين آلات و ابزار ، عبارت از دستگاه ها ، تجهيزات ، ماشين آلات  و به طور كلي ، ابزار هاي اجراي كار است كه به منظور اجراي موضوع پيمان به صورت موقت به به كار گرفته مي شود . ماشين آلات و ابزار را ممكن است ماشين آلات نيز به نامند .
ه) تاسيسات و ساختمان هاي موقت ، عبارت از انواع ساختمان ها ، محوطه سازيها ، انبارها ، تاسيسات آب ، برق ، سوخت و مخابرات ، شالوده دستگاه ها ، و به طور كلي ، تمام تاسيسات و بناهايي است كه به صورت موقت ، براي دوره اجرا تامين شده و جزء كار هاي تجهيز كارگاه به شمار مي رود .
و) وسايل ، عبارت از اثاثيه اداري ، مسكوني آشپزخانه و ديگر لوازم مورد نيازي است كه براي دوره اجرا تامين شده و جزو  تجهيز كارگاه منظور مي شود .', 'این ماده بیان‌کننده تعاریف مربوط به مصالح، تجهیزات، ماشین‌آلات و امکانات مورد استفاده در اجرای پیمان است. بر اساس این حکم، اقلامی که در اجرای کار مصرف، نصب یا باقی می‌مانند از مصالح و تجهیزات محسوب شده و اقلامی که صرفاً برای انجام موقت عملیات استفاده می‌شوند در حکم ماشین‌آلات و ابزار اجرایی هستند. هدف از این مقرره، تفکیک اموال و تجهیزات مرتبط با کار دائم و موقت و تعیین مسئولیت طرفین نسبت به آنها می‌باشد.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (14, 1, 14, 'برآورد هزينه اجراي كار ، مبلغ پيمان ، مبلغ اوليه پيمان ، مبلغ نهايي پيمان ، ضريب پيمان ، نرخ پيمان ، مدت پيمان ، مدت اوليه پيمان ، متوسط كاركرد فرضي ماهانه', 'الف ) برآورد هزينه اجراي كار، مبلغي است كه به عنوان هزينه اجراي موضوع پيمان ، به وسيله كارفرما محاسبه و اعلام شده است .
ب) مبلغ پيمان ، مبلغ درج شده در ماده 3 موافقت نامه يا احتساب مبلغ ناشي از تغيير مقادير كار قيمت جديد است . مبلغ پيمان هنگام مبادله پيمان ، همان مبلغ درج شده در ماده 3 موافقت نامه است كه مبلغ اوليه پيمان ناميده
 مي شود .
ج)مبلغ نهايي پيمان ، مبلغ درج شده در ماده 3 موافقت نامه و تغييرات احتمالي است كه بر اساس اسناد و مدارك پيمان ، در آن ايجاد شده مي شود .
د) ضريب پيمان ،حاصل تقسيم مبلغ اوليه پيمان به مبلغ برآورد هزينه اجراي كار است .
ه) نرخ پيمان ، در مورد هر يك از اقلام كار عبارت است از بهاي واحد آن قلم در فهرست بهاي منضم به پيمان با اعلام ضريب پيمان و ضريب هاي پيش بيني شده در فهرست بها و مقادير كار است .
در پيمانهايي كه مشمول تعديل آحاد بهاء هستند ، نرخ پيمان ، نرخ محاسبه شده به روش پيشگفته ، پس از اعمال تعديل آحاد بها مي باشد .
و) متوسط كاركرد فرضي ماهانه ، عبارت است از حاصل تقسيم مبلغ اوليه پيمان به مدت اوليه پيمان است .
ز) ، مدت پيمان يا مدت اجراي پيمان ، مدت درج شده در بند ماده 4 موافقت نامه و تغييرات احتمالي است كه بر اساس ماده 30 در آن ايجاد مي شود . مدت پيمان هنگام مبادله پيمان ، همان مدت درج شده در ماده 4 موافقت نامه است كه مدت اوليه پيمان ناميده مي شود .', 'این ماده بیان‌کننده مفاهیم مالی و زمانی مرتبط با پیمان از جمله مبلغ پیمان، برآورد هزینه، مدت پیمان و شاخص‌های محاسباتی است. بر اساس این حکم، مبانی مالی و زمانی قرارداد باید به صورت دقیق مشخص شده و در طول اجرای پیمان ملاک محاسبه تعهدات طرفین قرار گیرد. هدف از این مقرره، ایجاد شفافیت در محاسبات مالی و کنترل مدت اجرای پروژه است.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (15, 1, 15, 'روز ، ماه ، تاريخ ها ، مفرد و جمع ، عنوان ها', 'الف) روز و ماه روز و ماه  تقويمي و شمسي است .
ب) تاريخ طبق تقويم رسمي كشور است .
ج) هر جا كه معناي عبارت ايجاب كند ، كلمه مفرد معناي جمع و كلمات جمع معناي مفرد دارد .
د) عنوان هاي به كار رفته در متون موافقت نامه يا شرايط عمومي و ديگر قسمت هاي اسناد و مدارك پيمان ، صرفاً به منظور راهنمايي و آگاهي از مفاد اسناد و مدارك است و نمي توان در تفسير اسناد و مدارك پيمان ، از آنها استفاده كرد .', 'این ماده بیان‌کننده نحوه استفاده از اصطلاحات زمانی، عناوین و مفرد یا جمع بودن واژه‌ها در اسناد پیمان است. بر اساس این حکم، تفسیر عبارات قرارداد باید مطابق تعاریف ارائه‌شده در پیمان انجام شود. هدف از این مقرره، جلوگیری از ابهام در برداشت از مفاد قرارداد و ایجاد وحدت رویه در تفسیر اسناد پیمان است.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (16, 2, 16, 'تاييدات پيمانكار', 'موارد زير را پيمانكار تعيين مي كند :
الف ) تمام اسناد و مدارك موضوع ماده 2 موافقت نامه را مطالعه نموده و از مفاد آن كاملاً آگاه شده است .
ب) نسبت به تامين نيروي انساني مورد نياز و تدارك مصالح ، تجهيزات ، ماشين آلات و ابزار اجراي كار طبق مشخصات در محل با از نقاط ديگر ، اطمينان يافته است .
ج) محل اجراي كار را ديده و بررسي كرده است و از وضعيت آب و هوا ، بارندگي ف و امكان اجراي كار در فصل هاي مختلف سال ، با توجه به آمار 20 پيش از تاريخ ارائه پيشنهاد قيمت و در نظر گرفتن مدت اجراي كار ، اطلاع يافته است .
د) از قوانين و مقررات مربوط به كار ، بيمه هاي اجتماعي، ماليات ها ، عوارض ، و ديگر قوانين  و مقررات ، كه تا تاريخ تسليم پيشنهاد معمول و مجرا بوده است ، كاملاً مطلع بوده و متعهد است كه همه آنها را رعايت نمايد . در هر حال ، مسئوليت عدم رعايت قوانين  و مقررات ياد شده ، بر عهده پيمانكار است .
ه) در تهيه پيشنهاد قيمت ، سود مورد نظر خود و تمام هزينه هاي ناشي از مفاد بند هاي بالا را در نظر گرفته و بعداً از هيچ بابت ، حق درخواست اضافه پرداختي ندارد .
به هر حال ، پيمانكار تاييد مي كند كه هنگام تسليم پيشنهاد ، مطالعات كافي انجام داده و هيچ موردي باقي نمانده است كه بعداً در مورد استناد به جهل خود نمايد .', '1- اصل بر این است که از متخصصان خارجی استفاده نشود مگر در موارد ضروری و دلیل اینکه در بند الف ماده 17 پیمانکار باید موضوع استخدام متخصصان خارجی را به اطلاع کارفرما برساند. بر میگردد به بند الف ماده 38 شرایط عمومی پیمان که :«برای استخدام متخصصان خارجی در اسناد و مدارک پیمان، پرداخت ارز از سوی کارفرما تعهد شده باشد، .......، به شرط آنکه در قرارداد آنها، قسمتی از حقوق که هیچگاه نباید از 50 درصد بیشتر باشد، به ارز پیش‌بینی شده باشد»

2- بر اساس ماده 151 قانون کار در کارگاه هایی که به مدت محدود به منظور انجام کار معینی دور از مناطق مسکونی ایجاد می شوند، پیمانکاران موظفند سه وعده غذایی مناسب و ارزان قیمت (صبحانه،ناهار و شام) برای کارگران خود فراهم کند که حداقل یک وعده آن غذای گرم باشد.»

3- ممکن است پیمانکار علاوه بر کارکنان خود بر اساس اسناد و مدارک پیمان از جمله شرایط خصوصی پیمان برای کارکنان کارفرما و مهندس مشاور تامین رفاه داشته باشد. «گر در اسناد و مدارک پیمان، تکلیفی برای تهیه غذا، مسکن و دفتر کارکنان کارفرما مهندس مشاور و آزمایشگاه در محل کار به‌عهده پیمانکار گذاشته شود، پیمانکار موظف به تأمین آن‌ها، طبق شرایط پیش‌بینی شده، می‌باشد. »  که در ماده 20 ح شرایط خصوصی شرایط آن تعیین می شود.

4-  پیمانکار باید کارنامه کارکرد روزانه را برای تمامی کارگرانش تهیه کند.

5- در صورت وجود کارگرانی که مخل کارگاه باشند ابتدا مهندس ناظر به رئیس کارگاه تذکر می دهد  و در صورت تکرار پیمانکار باید نسبت به برکناری کارگران مخل اقدام کند 1- تاخیر در پرداخت دستمزد کارگران و تکرار آن توسط پیمانکار نشان می دهد او قصد ادامه عملیات اجرایی پیمان را ندارد. زیرا تاخیر در پرداخت دستمزد کسانی که موضوع پیمان به فکر و توان آنها محقق می شود، قطعاً اجرای کار را به سرانجام نمی رساند.
2- اگر پیمانکار توان مالی خود را از دست دهد، تاخیر در پرداخت حقوق کارگران نشانه بارز ورشکستگی پیمانکار دارد که ورشکستگی پیمانکار یکی از موارد تحقق فسخ پیمان مطابق جز 11 بند الف ماده 46 شرایط عمومی پیمان پیش بینی شده است.
3- پیمانکار از نظر مالی چنان دچار استیصال شده که حتی بدیهی ترین حقوق کسانی که کار پیمان را انجام می دهند، عاجز است و چنین پیمانکاری قطعاً از انجام تعهدات ناشی از پیمان عاجز خواهد بود.
4- کارفرما به عنوان دولت برای احقاق حقوق ضعیف ترین قشرهای جامعه بی تفاوت نیست و حقوق آن ها را در پیمان تضمین می کند.
5- در صورت وجود کارگرانی که مخل کارگاه باشند ابتدا مهندس ناظر به رئیس کارگاه تذکر می دهد  و در صورت تکرار پیمانکار باید نسبت به برکناری کارگران مخل اقدام کند.
6- دلیل اینکه کارفرما برای حقوق معوقه کارگران ورود می کند از لحاظ امنیتی و منطقه ای بسیار مهم است.
7- در صورت وقوع( بند «و» ماده 17) کارفرما باید تمام جوانب را بسنجد تا حقوق پیمانکار نیز تضییع نگردد.
8-کارفرما خود نباید مسبب تاخیر در پرداخت دستمزد کارگران باشد. زیرا در صورتی که کارفرما در زمان های مقرر نسبت به تعهدات مالی اقدام کند امکان عدم پرداخت حقوق کارگران به حداقل می رسد..');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (17, 2, 17, 'كاركنان', 'الف ) پيمانكار متعهد است كه عمليات موضوع پيمان را به وسيله افرادي كه در كار خود تخصص و تجربه كافي دارند ، انجام دهد . كساني كه در اجراي اين پيمان ، خدماتي براي پيمانكار انجام دهند ، كاركنان پيمانكار شناخته مي شوند . اگر در اسناد و مدارك پيمان ، استفاده از متخصصان خارجي  پيش بيني شده باشد ، پيمانكار متعهد است قبلاً وضعيت استخدام مانند ميزان حقوق مزايا ، مدت استخدام و محل اقامت و مشخصات آنها را به وسيله مهندس مشاور به اطلاع كارفرما برساند و با رعايت مقررات ذي ربط  و تامين هزينه هاي مربوط ، براي استخدام آنها اقدام كند . كارفرما تسهيلات لازم را براي استخدام متخصصان ياد شده  فراهم مي نمايد . تشخيص لزوم و حدود تسهيلات مزبور با كارفرماست و اين مساعدت از مسئوليت پيمانكار نمي كاهد .
ب) تامين نيروي انساني مورد نياز و محل سكونت مناسب ، آب آشاميدني و روشنايي كافي براي آنها به عهده پيمانكار است .
پيمانكار بايد براي تدارك دايمي آذوقه كارگران ، اقدامات لازم به عمل آورد، بدون آنكه اين اقدام براي وي حق انحصار ايجاد كند و به آزادي كارگران در تامين مواد مورد نياز آنها ، از هر منبعي كه مايل به تحصيل‌ آن باشد محدوديتي وارد سازد . بهاي آذوقه كه بدين ترتيب از طرف پيمانكار تهيه مي شود ، نبايد از بهاي جنس مشابه در نزديكترين شهر يا محل گرانتر باشد و پيمانكار نمي تواند هزينه هاي ديگر ، مانند هزينه حمل را به قيمت هاي خريد اضافه كند .
ج) كاركنان ايراني كارگاه بايد داراي شناسنامه ، و كاركنان بيگانه بايد داراي پروانه اقامت و اجازه مار باشند .
د) پيمانكار نبايد شاغل كارفرما ، وزارتخانه ها ، سازمانها و شركت هاي دولتي و شهرداريها را بدون اجازه  مسئولان ذي ربط استخدام نمايد . همچنين پيمانكار بايد از به كار گماشتن اشخاصي كه استخدام آنها از نظر اداره وظيفه عمومي مجاز نيست ، خودداري كند .
ه) پيمانكار موظف است كه براي كارگران كارنامه كاركرد روزانه صادر كند و در اختيار آنان قرار دهد . مهندس ناظر مي تواند از ادامه كار كارگران بدون كارنامه جلوگيري نمايد .
و) پيمانكار متعهد است كه دستمزد كارگران خود را طبق قانون كار مرتباً پرداخت نمايد . در صورتي كه پرداخت دستمزد كارگران تاخيري  پيش آيد ، مهندس مشاور به پيمانكار اخطار مي كند كه طلب كارگران را پرداخت نمايد . در صورت استنكاف پيمانكار ، كارفرما مي تواند دستمزد كارگران را براي ماه يا ماه هايي كه صورت وضعيت آن به پيمانكار پرداخت شده است ، طبق كارنامه هاي كارگري كه در دست كارگران و داراي امضاي رئيس كارگاه است ، با توجه به پرداخت هاي علي الحساب  كه به آنها شده است ، با حضور نماينده مهندس مشاور و پيمانكار ، از محل مطالبات پيمانكار پرداخت كند و مبلغ پرداختي را به اضافه 15 درصد ، به حساب بدهي پيمانكار منظور كند . در صورتي كه نماينده پيمانكار ، با وجود اخطار مهندس مشاور از حضور براي پرداخت ها خودداري كند ، كارفرما پرداخت مزبور را انجام مي دهد ، بدون اين كه پيمانكار حق اعتراضي بر اين عمل و مبلغ پرداختي و تعداد كارگران و ميزان استحقاقي آنان داشته باشد . در صورت تكرار تاخير در پرداخت دستمزد كارگران به مدت بيش از يك ماه ، براي ماهي كه صورت وضعيت آن پرداخت شده است ، كارفرما مي تواند پيمان را فسخ نمايد .
ز)پيمانكار مي كوشد تا حد ممكن ، كارگران مورد نياز خود را از بين ساكنان منطقه اجراي كار ، كه صلاحيت انجام كار هاي موضوع پيمان را داشته باشند ، انتخاب كند و به كار گمارد.
ح) پيمانكار موظف به اجراي مقررات بيمه هاي درماني و اجتماعي ، مقررات و دستور العمل هاي حفاظتي فني و بهداشت كار است .
ط) در اجراي اين پيمان ، پيمان كار در مقابل كارفرما مسئول اعمال كاركنان خود است ، هرگاه كاركنان و كارگران پيمانكار و پيمانكاران جزء ، صلاحيت لازم را براي انجام كار مربوط را نداشته باشد يا باعث اختلال نظم كارگاه شوند ، مهندس مشاور يا مهندس ناظر ، مراتب را براي بار اول به رئيس كارگاه تذكر مي دهد ، و در صورت تكرار ، مي تواند از پيمانكار بخواهد كه متخلفان را از كار بركنار كند . در اين صورت پيمانكار مكلف به اجراي اين دستور است و حق ندارد بركنار شدگان را بار ديگر در همان كارگاه به كار گمارد . اجراي اين دستور از مسئوليت هاي پيمانكار نمي كاهد و ايجاد حقي براي او نمي كند .', 'این ماده بیان‌کننده وضعیت و مسئولیت کارکنان پیمانکار در اجرای موضوع پیمان است. بر اساس این حکم، پیمانکار موظف است نیروی انسانی مورد نیاز و دارای صلاحیت را برای انجام عملیات فراهم کرده و مسئولیت عملکرد آنان را بر عهده داشته باشد. هدف از این مقرره، تضمین اجرای صحیح کار و تعیین مسئولیت پیمانکار نسبت به عوامل اجرایی است.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (18, 2, 18, 'مسئوليت حسن اجراي كار ، برنامه كار ، گزارشي پيشرفت كار ، هماهنگي با پيمانكاران ديگر ، رئيس كارگاه', 'الف) پيمانكار مسئوليت كامل حسن اجراي كار هاي موضوع پيمان  را طبق اسناد و مدارك پيمان به عهده دارد .
ب)پيمانكار متعهد است كه سازمان ، روش اجرا و برنامه زماني تفصيلي اجراي كار را طبق نظر مهندس مشاور بر اساس نقشه هاي موجود  و برنامه زماني كلي تهيه كند و ظرف مدت يك ماه از تاريخ مبادله پيمان ، يا مدت ديگري كه در اسناد و مدارك پيمان تعيين شده است ، تسليم مهندس مشاور نمايد  يا پس از اصلاح و تصويب كارفرما براي اجرا به پيمانكار ابلاغ شود . اگر اسناد و مدارك پيمان ، جزئياتي براي چگونگي تهيه برنامه زماني تفصيلي و به هنگام كردن آن تعيين شده باشد ، پيمانكار ملزم به رعايت آن مي باشد .
ج) در صورتي كه حين اجراي كار ، پيمانكار تشخيص دهد كه تغييراتي در برنامه زماني تفصيلي ضروري است ، موظف است پيش از رسيدن موعد انجام كارهايي كه به نظر او بايد در برنامه آن تغيير داده شود ، مراتب را با ذكر دليل ، به مهندس مشاور اطلاع دهد . مهندس مشاور ، تغييرات مورد تقاضاي پيمانكار را در قالب برنامه زماني كلي رسيدگي مي كند و آنچه را كه مورد قبول است ، پس از تصويب كارفرما ، به پيمانكار ابلاغ مي كند . بديهي است كه اين تغييرات در حدود مندرجات پيمان ، از ميزان تعهدات و مسئوليت هاي پيمان كار نمي كاهد .
اگر تغيير برنامه زماني تفصيلي  از سوي مهندس مشاور مطرحشود ، پيمانكار با توجه به نظر مهندس تغييرات برنامه زماني تفصيلي را تهيه مي كند و به شرح پيشگفته ، براي طي مراتب بررسي و تصويب ، تسليم مهندس مشاور مي نمايد .
د ) پيمانكار متعهد است كه هماهنگي لازم را با ديگر پيمانكاران يا گرو هاي اجرايي متعلق به كارفرما كه به نحوي با موضوع قرارداد مرتبطند به عمل آورد . برنامه ريزي چگونگي اين هماهنگي توسط مهندس مشاور به پيمانكار ابلاغ مي شود.
ه ) پيمانكار مكلف است كه در پايان هر ماه ، گزارش كامل كار هاي انجام شده در آن ماه را تهيه نمايد . شكل و چگونگي تهيه گزارش مهندس مشاور تعيين مي كند . اين گزارش شامل مقدار و درصد فعاليت هاي انجام شده ، ميزان پيشرفت با تاخير نسبت به برنامه زماني تفصيلي ، مشكلات و موانع اجرايي ، نوع و مقدار مصالح و تجهيزات وارد شده به كارگاه ، تعداد و نوع ماشين‌ آلات موجود و آماده به كار ، تعداد و تخصص نيروي انساني موجود و ديگر اطلاعات لازم مي باشد . در صورتي كه جزئيات ديگري براي چگونگي تهيه گزارش پيشرفت كار در اسناد و مدارك پيمان تعيين شده باشد ، پيمانكار موظف به رعايت آن مي باشد .
ز)پيمانكار بايد پيش از آغاز عمليات ، شخص واجد صلاحيتي را كه مورد قبول مهندس مشاور باشد به عنوان رئيس كارگاه معرفي نمايد . رئيس كارگاه بايد در اوقات كار در كارگاه حاضر باشد و عمليات اجرايي ، با مسئوليت و نظارت او انجام شود . اگر ضمن كار معلوم شود كه رئيس كارگاه قادر به انجام وظايف خود نيست ، مهندس مشاور با ذكر دليل ، درخواست تعويض او را از پيمانكار خواهد كرد و پيمانكار مكلف است ظرف يك ماه ، شخص واجد صلاحيت ديگري را كه مورد قبول مهندس مشاور باشد معرفي نمايد .
پيمانكار بايد به منظور اجراي كار و دريافت دستور كارها و نقشه ها از مهندس مشاور و همچنين براي تنظيم صورت وضعيت هاي موقت ، اختيارات  كافي به رئيس كارگاه بدهد . هر نوع اخطار و اعلام كه مربوط به اجراي كار باشد و از طرف مهندس مشاور يا نماينده او به رئيس كارگاه ابلاغ شود ، در حكم  ابلاغ به پيمانكار است .
پيمانكار مي تواند در صورت لزوم ، رئيس كارگاه را عوض كند ، مشروط به اينكه پيش از تعويض ، مراتب را به اطلاع مهندس مشاور برساند و صلاحيت جانشين او مورد قبول نامبرده باشد', 'این ماده بیان‌کننده تعهدات پیمانکار در خصوص حسن اجرای کار، تهیه برنامه اجرایی و هماهنگی با عوامل مرتبط با پروژه است. بر اساس این حکم، پیمانکار باید عملیات را مطابق برنامه و تحت مدیریت رئیس کارگاه انجام دهد. هدف از این مقرره، ایجاد نظم اجرایی، کنترل پیشرفت کار و جلوگیری از تأخیر یا اختلال در اجرای پروژه است.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (19, 2, 19, 'كنترل نقاط نشانه ، پياده كردن نقشه ها ، اندازه گيري', 'الف) پيمانكار ، پيش از آغاز عمليات موضوع پيمان ، بايد نقاط نشانه م مبداء را از لحاظ تطبيق با نشانه ها كنترل نمايد و در صورتي كه اختلافي موجود نباشد ، درستي آنها را تائيد و اعلام دارد و در صورتي كه اختلافي وجود داشته باشد، مراتب را به اطلاع مهندس مشاور برساند تا وضع موجود با مهندس مشاور و كارفرما صورت جلسه شود و ملاك شروع عمليات قرار گيرد . بديهي است كه پس از آغاز عمليات ، هيچ گونه اعتراضي از جانب پيمانكار در اين زمينه پذيرفته نيست .
پس از تحويل هر قسمت از كارگاه ، پيمانكار بايد بي درنگ ، نقاط نشانه و مبداء و همچنين علايم مربوط به آنها را با بتن يا مصالح بنايي تثبيت نمايد و در طول مدت اجراي كار تا تحويل موقت ، به هزينه خود ، حفظ و نگه داري كند .
ب) پيمانكار متعهد است كه نقشه ها ، امتدادها و محورها را با نظارت مهندس مشاور پياده كند و درستي آنها را با مهندس مشاور صورت جلسه كند . در صورتي كه هنگام پياده كردن نقشه ها ، امتدادها و محورها ، اختلافي در مورد تراز زمين طبيعي با تراز آنها در مدارك فني مشاهده شود ، وضع موجود را پيمانكار و مهندس مشاور و كارفرما صورت جلسه مي كنند .
تراز كف پي بناها وزير سازي راهها تمام عملياتي كه پس از انجام كار پوشيده مي شوند و بعداً مرئي نيستند ، يا به هر صورت ، كنترل و اندازه گيري كامل آنها ميسر نباشد ، بايد پيش از پوشيده شدن يا از بين يا از بين رفتن آثار آنها ، صورت مجلس شود و به امضاي مهندس ناظر و رئيس كارگاه برسد . اين صورت مجلسها ، ملاك اندازه گيري ها در تنظيم صورت وضعيت هاست . اگر پيمانكار عملياتي را كه بايد مورد آزمايش يا بازديد قرار گيرد و تاييد شود ، پيش از اينكه اقدامات پيشگفته انجام شود بپوشاند ، موظف است پوشش هاي انجام شده را به هزينه خود بردارد و پس از انجام آزمايشها و بازديدها و بازديد هاي لازم و تائيد انجام كار از سوي مهندس ناظر ، به هزينه خود ، نسبت به پوشش مجدد و اصلاح كار اقدام كند .
ج) اندازه گيري ها بر اساس نقشه هاي اجرايي ، دستور كارهاي اجرا شده و صورت جلسه ها ، كه شامل كروكي هاي لازم و روشن است ، انجام مي شود .', '1- بر اساس جز 1 بند ب ماده 20 مصالح و تجهیزات باید از محل معینی که در اسناد و مدارک پیمان تعیین شده تهیه شوند. در کل پیمانکار موظف است تهیه مصالح را از نظر مرغوبیت کاملاً مطابق با مشخصات فنی و مورد تایید مهندس مشاور تهیه نماید.
2- کارفرما می توادن در طول اجرای پروژه محل تهیه مصالح را تغییر دهد. این تغییر محل می تواند برای کارفرما از نظر مسافت یا عوامل دیگر بار مالی داشته باشد.
3- تمامی مصالحی که وارد کارگاه می شود می بایستی توسط رئیس کارگاه و ناظر مشاور صورتجلسه شوند.
4-  در صورتی که که تامین برخی کالا مطابق با اسناد و مدارک پیمان به عهده کارفرما باشد باید جهت تهیه به موقع آن ها اقدام کند. زیرا در صورتی که کل پروژه به آن تهیه آن کالا وابسته باشد و کارفرما در تهیه آن ها عاجز باشد، باید پیمان را تعلیق کند و هزینه های بالاسری را مطابق ماده 49 شرایط عمومی پیمان پرداخت کند.
5- پیمانکار حق خروج ماشین الاتی که در پروژه فعال هستند را ندارد و فقط ماشین آلاتی که نیاز پروژه نیستند را به صورت مکتوب به اطلاع مهندس مشاور می رساند و در صورت صلاح دید مشاور، پیمانکار می تواند آن ماشین آلات را از کارگاه خارج نماید.
6- در صورتی که در ماده 20-ح شرایط خصوصی پیمان شرایطی برای تهیه غذای کارکنان کارفرما، مهندش مشاور و آزمایشگاه دیده شده است، پیمانکار موظف به تهیه غذا مطابق با لیست اعلامی می باشد اصولاً ماشین آلات، نیروی اسنانی و مصالح سه ضلع مثلثی هستند که پیمانکار در اجرای تعهدات خود به کارفرما به آن ها نیاز مبرم دارد. خرابی یا نبود هر کدام از این اضلاع می تواند تکمیل عملیات اجرایی  موضوع پیمان را ناکام گذارد..');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (20, 2, 20, 'تجهيز كارگاه ، تدارك مصالح ، تجهيزات و ماشين آلات', 'الف) پيمانكار موظف است كه پس از تحويل گرفتن كارگاه ، با توجه به مدت تعيين شده براي تجهيز ، طرح جانمايي تجهيز كارگاه را ت تهيه كرده و پس از تائيد مهندس مشاور ، آن را مبناي تجهيز كارگاه قرار دهد . تامين آب ، برق ، سوخت  و مخابرات ، و به طور كلي ، تجهيز كامل كارگاه ، به نحوي كه براي اجراي كار طبق اسناد و مدارك پيمان لازم است ، به عهده پيمانكار مي باشد ، مگر آنكه در اسناد و مدارك پيمان ، ترتيب ديگري پيش بيني شده باشد .
ب) تامين نيروي انساني ، مصالح و تجهيزات ، ماشين آلات و ابزار به عهده پيمانكار است ، مگر آنكه در اسناد و مدارك پيمان ، ترتيب ديگري پيش بيني شده باشد .
مصالح و تجهيزاتي كه پيمانكار براي انجام عمليات موضوع پيمان تهيه و در كارگاه نگه داري مي كند ، بايد به قرار زير باشد :
اگر منابع تهيه مصالح و تجهيزات در اسناد و مدارك پيمان تعيين شده  يا بعداً معين مي شود ، بايد از همان منابع تهيه گردد . نمونه يا كاتالوگ فني مصالح و تجهيزات يابد از نظر تطبيق با مشخصات فني ، بيش از سفارش ، به تائيد مهندس مشاور برسد . در هر حال ، از نظر مرغوبيت بايد كاملاً طبق مشخصات فني باشد و مورد تائيد مهندس مشاور قرار بگيرد .
ذكر منابع تهيه مصالح و تجهيزات در اسناد و مدارك پيمان يا تعيين آنها ضمن اجرا ، از تعهدات پيمانكار در قبال تهيه مصالح مرغوب و كافي نمي كاهد . بدين روي ، پيمانكار موظف است با مطالعه كافي نسبت به امكانات محلي و كيفيت منابع تهيه مصالح و تجهيزات ، نظر و پيشنهاد خود را تسليم مهندس مشاور كند . در صورتي كه استفاده از اين قبيل منابع مورد موافقت مهندس مشاور و كارفرما قرار بگيرد ، اقدام به تهيه و حمل آنها نمايد . بديهي است كه كارفرما اين حق را دارد كه منابع تهيه مصالح را تغيير دهد و پيمانكار موظف به رعايت آن مي باشد . اگر به مناسبت اين تغيير محل ، اضافه يا كسر هزينه اي بابت تغيير مسافت حمل يا عوامل ديگر ايجاد شود ، تفاوت بهاء ، به اقتضاي مورد ، از پيمانكار كسر يا به او پرداخت مي شود . پيمانكار ملزم به رعايت مقررات مربوط به استخراج و بهره برداري شن و ماسه و ديگر مصالح معدني است .
نوع ، مقدار و تاريخ ورود مصالح و تجهيزات به كارگاه بايد با مهندس ناظر صورت جلسه شود . مصالح بايد به طور مرتب به نحوي انبار شود كه تمام آن به سهولت قابل بازرسي ، شمارش يا اندازه گيري باشد . انبار مصالح بايد از هر لحاظ قابل حفاظت بوده تا مصالح در مقابل عوامل جوي و عوامل ديگر مصون باشد .
ج) هر گاه تهيه و يا توزيع مصالح و لوازمي در داخل كشور در انحصار دولت باشد ، كارفرما تسهيلات لازم را براي تهيه آن مصالح و لوازم فراهم مي كند . اگر تهيه بعضي از مصالح و لوازم ، طبق مشخصات ذي ربط در داخل كشور ميسر نباشد و ورود آنها هم از طرف دولت ممنوع شده يا بشود ، كارفرما يا خودش اجازه ورود مصالح و لوازم مزبور را براي پيمانكار تحصيل مي كند يا مشخصات را تغيير مي دهد .
د) در مواردي كه مصالح و تجهيزاتي  بايد به وسيله پيمانكار از خارج از كشور تهيه شود ، كارفرما اجازه ورود آنها را از سازمان هاي ذيربط به هزينه پيمانكار تحصيل مي نمايد . هر گاه ضمن اجراي كار ، محدوديت هاي جديدي پيش آيد كه به علت آن ، پيمانكار نتواند مصالح و تجهيزات مورد نياز اجراي كار را در مدتي كه برنامه پيشرفت كار ايجاد مي كند از خارج از كشور تهيه و وارد كند ، مراتب را با ذكر دليل و ارائه اسناد از طريق مهندس مشاور به اطلاع كارفرما مي رساند تا با توجه به برنامه زماني اجراي كار ، كارفرما در مورد چگونگي تامين اين قبيل مصالح و تجهيزات ، تصميم گيري نمايد .
ه) در صورتي كه در اسناد و مدارك پيمان ، مشخصاتي براي ماشين آلات و ابزار اجراي كار تعيين شده باشد ، پيمانكار بايد آنها را طبق مشخصات تعيين شده ، تامين كند . هر گاه ضمن اجراي كار ، مهندس مشاور تشخيص دهد كه ماشين آلات و ابزار موجود پيمانكار ، براي اتمام كار در مدت پيمان كافي نيست يا مشخصات آنها براي اجراي كار مناسب نيست ، مراتب را به پيمانكار ابلاغ مي كند . پيمانكار مكلف است كه ماشين آلات و ابزار خود را طبق نظر مهندس مشاور و در مدتي كه نامبرده تعيين مي نمايد ، تكميل و تقويت كند ، بدون اينكه براي اين كار ، ادعاي خسارت يا هزينه هاي اضافي از كارفرما داشته باشد .
و) پيمانكار نمي تواند ماشين آلات و ابزار را كه براي انجام عمليات لازم است ، از كارگاه خارج كند . در مورد بيرون بردن ماشين آلات كه در كارگاه مورد نياز نيست ، پيمانكار ، تقاضاي بيرون بردن ماشين آلات مزبور را به مهندس مشاور تسليم مي كند . مهندس مشاور به تقاضا ي او رسيدگي مي كند ، و در صورتي كه موجه باشد ، اجازه خروج مي دهد .
ز) در صورتي كه طبق اسناد و مدارك پيمان ، تامين اقلامي از تجهيزات كه پيمانكار بايد نصب كند و به طور دايم در كار باقي بماند ، در تعهد كارفرما باشد ، پيمانكار مسئول عملكرد ناقص احتمالي اين تجهيزات  نيست ، مگر آنكه ثابت شود كه نقص آنها مربوط به كار پيمانكار است .
ح) اگر در اسناد و مدارك پيمان ، تكليفي براي تهيه غذا ، مسكن و دفتر كار كاركنان كارفرما، مهندس مشاور و آزمايشگاه در محل كار به عهده پيمانكار گذاشته شود ، پيمانكار موظف به تامين آنها، طبق شرايط پيش بيني شده ، مي باشد .', '1- پیمانکار مکلف است بر اساس بند ج ماده 21 شرایط عمومی پیمان پروژه را هزینه کارفرما و نزد موسسه مورد تایید کارفرما بیمه می کند. 
2-  در صورت کوتاهی پیمانکار در هرکدام از مقاد این ماده، کارفرما می تواند راساً موضوع را انجام و تمام هزینه ها بعلاوه 15 درصد به حساب بدهی پیمانکار قرار دهد.
3-  کار فرما موظف است بخش های پیمان را را به شکلی بیمه کند که در صورت بروز حادثه، مبلغ دریافتی خسارت بیمه گر کفاف برگشت کارهای موضوع پیمان به حالت اولیه را داشته باشد. در صورتی که این موضوع محقق نشود، جبران هزینه های خسارات وارده به عهده کارفرما می باشد.
4- در صورتی که پروژه در مدت زمان معین شده در موافقت نامه به پایان نرسد:
الف) در صورتی که تاخیرات پیمانکار مجاز شناخته شود، هزینه تمدید بیمه نامه به عهده کارفرما می باشد.
ب) در صورتی که تاخیرات پیمانکار غیر مجاز شناخته شود، هزینه تمدید پیمان به عهده پیمانکار است.
5- پیمانکار باید تمام ساختمان‌ها و تأسیسات موقت، ماشین‌آلات ابزار و وسایل کارگاه متعلق به خود را بیمه و در اختیار کارفرما قرار دهد.
6- در صورتی که پیش بینی در خصوص ایجاد و نگهداری راه های انحرافی در اسناد و مدارک پیمان نشده باشد، این هزینه ها به عهده پیمانکار است');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (21, 2, 21, 'حفاظت از كار و شخص ثالث ، بيمه كار ، مراقبت هاي لازم', 'الف) پيمانكار از روز تحويل كارگاه تا روز تحويل موقت عمليات موضوع پيمان ، مسئول حفظ و نگه داري كار هاي انجام شده ، مصالح ، ماشين آلات و ابزار ، زمينه ها راه ها ، تاسيسات و بناهايي مي باشد كه زير نظر و مراقبت او قرار دارد ، و به همين منظور ، اقدامات لازم را براي نگه داري و حفاظت آنها در داخل كارگاه در مقابل عوامل جوي و طغيان آب رودخانه ها و سرقت و حريق و مانند اينها به عمل مي آورد .
ب) پيمانكار در چارچوب مقررات و دستورالعمل هاي حفاظت فني و بهداشت كار ، مسئول خسارت هاي وارد شده به شخص ثالث در محوطه كارگاه است و در هر حال ، كارفرما در اين مورد هيچ نوع مسئوليتي بر عهده ندارد . كارفرما و مهندس مشاور مي توانند در صورت مشاهده عدم رعايت دستورالعمل هاي حفاظت فني و بهداشت كار ، دستور توقف بخشي از كار را كه داراي ايمني لازم نيست تا برقراري ايمني طبق دستورالعمل اي ياد شده صادر نمايد . در اين حالت ، پيمانكار حق مطالبه خسارت در اثر دستور توقف كار را ندارد .
پيمانكار متعهد است كه تدابير لازم را براي جلوگيري از وارد شدن خسارت و آسيب به املاك مجاور اتخاذ نمايد ، و اگر در اثر سهل انگاري او خسارتي به املاك و تاسيسات مجاور يا محصول آنها وارد آيد ، پيمانكار مسئول جبران آن مي باشد .
ج) پيمانكار مكلف است كه پيش از شروع كار ، تمام يا آن قسمت از كار هاي موضوع پيمان را كه در اسناد و مدارك پيمان تعيين شده است ، در مقابل مواردي از حوادث مذكور در اسناد ياد شده به نفع كارفرما نزد موسسه اي كه مورد قبول كارفرما باشد ، بيمه نموده و بيمه نامه ها را به كارفرما تسليم كند . بيمه نامه ها بايد تا تاريخ تحويل موقت اعتبار داشته باشد ، تا زماني كه تحويل موقت انجام نشده است ، پيمانكار مكلف است كه بيمه نامه ها را تمديد كند . كارفرما هزينه هاي مربوط به بيمه به شرح پيشگفته را در مقابل ارائه اسناد صادر شده از سوي بيمه گر ، عيناً به بيمه گر پرداخت مي كند .
آن قسمت از هزينه بيمه كه مربوط به مدت تاخير غير مجاز پيمانكار باشد ، به حساب بدهي پيمانكار منظور مي شود . در صورت بروز حادثه اي كه باعث از بين رفتن تمام يا قسمتي از كار هاي انجام شده و مصالح و تجهيزات پاي كار شود ، پيمانكار موظف است كه اولاً : مراتب را فراً به كارفرما و مهندس مشاور و طبق مقررات بيمه به بيمه گر اطلاع دهد و ثانياً طبق دستور كارفرما يا مهندس مشاور ، كارها را به حالت اوليه بازگرداند . برنامه زماني كار هاي پيش گفته توسط پيمانكار تهيه مي گردد و پس از تائيد مهندس مشاور و كارفرما به اجرا در مي آيد . كارفرما خسارت هاي وارد شده بر آنچه را كه بيمه شده است از بيمه گر وصل مي نمايد و مبلغ وصل شده از بيمه گر را براي تجديد عمليات به تناسب پيشرفت كار و طبق هزينه تمام شده ، اعم از هزينه مستقيم يا غير مستقيم ( بالاسري ) ، با تائيد مهندس مشاور به تدريج تا اعاده ي كار به حالت اوليه به پيمانكار پرداخت مي كند . كارفرما بايد موضوع پيمان كار را به نحوي بيمه كند كه در صورت بروز حادثه ، خسارت دريافتي از بيمه گر براي اعاده كارها  به حالت اوليه كافي باشد ، در صورتي كه تكليف بيمه كار در اسناد و مدارك پيمان تعيين نشده باشد ، پيش از شروع كار ، پيمانكار چگونگي بيمه كار را از كارفرما استعلام مي نمايد  و كارفرما در مدت 10 روز كارها و حوادث مشمول بيمه را تعيين و به پيمانكار ابلاغ مي نمايد تا پيمانكار طبق مفاد اين بند ، در مورد بيمه كار اقدام نمايد .
اگر كارفرما عمليات موضوع پيمان را بيمه نكند ، در صورت وقوع حادثه ، جبران خسارت هاي وارده شده به عهده او مي باشد .
د) پيمانكار مكلف است كه تمام ساختمانها و تاسيسات موقت ، ماشين آلات و ابزار و وسايل كارگاه را ، كه متعلق به اوست و يا در اختيار اوست و براي انجام عمليات موضوع پيمان به كار گرفته ، به هزينه خود بيمه كند و رونوشت بيمه ها را به كارفرما تسليم نمايد . ماشين آلات و ابزاري كه كارفرما در اختيار پيمانكار قرار مي دهد ، كارفرما بيمه مي كند .
ه) پيمانكار موظف است كه روشنايي قسمتهايي از داخل كارگاه را كه بايد روشن باشد تامين كند
 و همچنين تمام علائم راهنمايي و خطر و وسايل حفاظتي ، و در صورت لزوم ، حصاركشي را فراهم نمايد و تعداد كافي نگهبان و مراقب در هر جا كه لازم باشد ، بگمارد .
و) پيمانكار متعهد است كه عمليات اجرايي خود را طوري انجام دهد كه راه عبور مناسبي در پياده رو و سواره رو براي عبور و مرور رهگذران و وسائط نقليه همواره باز بماند و مصالح خود را در محل هايي انبار كند كه موجب ناراحتي يا زحمت ساكنان اطراف ، يا رهگذران نشود . استفاده از ماشين آلات و ابزار در ساعات عادي كار ، و در نتيجه ، صداي آنها و همچنين استفاده از راه هاي معين به منظور انجام عمليات ، مزاحمت تلقي نمي شود .
در مواردي كه اجراي كار ايجاب كند كه قسمتي از سواره رو و يا پياده رو براي مدت موقت و با اطلاع مهندس مشاور يا مهندس ناظر  به كلي مسدود شود ، پيمانكار با كسب مجوز لازم از مقامات محلي ، عبور و مرور را با راه هاي انحرافي كه مسير آنها بايد به تائيد مهندس مشاور برسد تامين كند . كارفرما نيز مساعدت لازم را براي تحصيل مجوز هاي مورد نياز به عمل مي آورد .
اگر ترتيب احتساب و پرداخت هزينه ايجاد و نگه داري راه هاي انحرافي در اسناد و مدارك پيمان معين نشده باشد اين هزينه ها به عهده پيمانكار است . همچنين پيمانكار متعهد است كه در حمل مصالح و ماشين آلات و عبور آنها از راهها ، پلها و تونلها ، رعايت قوانين ، مقررات و استانداردها را بكند و اگر عبور ماشين يا مصالحي ترتيب خاصي را ايجاد كند ، با نظر كارفرما يا مهندس مشاور اقدام نمايد . هر گاه پيمانكار بر خلاف مفاد اين بند ، رفتار نمايد مسئول جبران خسارت هاي وارد شده مي باشد .
ز) پيمانكار متعهد است كه انتظامات كارگاه را تامين نمايد و از ورود اشخاص غير مجاز و كساني كه باعث اختلال نظم كارگاه مي شود خود يا توسط مقامات انتظامي جلوگيري كند .
ح) هرگاه پيمانكار در اجراي تمام يا قسمتي  از موارد درج شده در اين ماده سهل انگاري يا كوتاهي كند و از انجام تعهداتي كه طبق آن به عهده گرفته است خودداري نمايد ، كارفرما حق دارد آن تعهدات را به جاي پيمانكار انجام دهد و هزينه هاي انجام شده و خسارت وارده را به اضافه 15 درصد به حساب بدهي پيمانكار منظور كرده و از مطالبات وي كسر نمايد . در اين صورت ، هر گونه ادعاي پيمانكار نسبت به اين قبيل پرداخت ها و همچنين نسبت به تشخيص كارفرما ، خواه از نظر اساس تخلف و خواه از نظر مبلغ پرداختي ، بي اثر مي باشد .', '1- با توجه به اینکه در ماده 2 موافقت نامه پیمان مشخصات فنی اعم از خصوصی و عمومی به همراه نقشه ها، دستور کارها و صورتجلسات از اسناد و مدارک پیمان به حساب می آیند، در صورت اختلاف این اسناد برای طرفین قابل استناد هستند. لذا در این ماده به نحوه گردش مدارک اشاره شده است.
2- مهندس مشاور موظف است تمامی دستور کارها را به صورت کتبی ارائه دهد. در صورت دستور کار شفاهی، پیمانکار می تواند از انجام آن خودداری کند.
3- در ابتدای پروزه دو نسخه از نقشه ها به صورت رایگان در اختیار پیمانکار قرار می گیرد.
4- پیمانکار موظف است قبل از شروع هر بخش از کار نقشه ها و مشخصات را مطالعه کند و اگر ابهامی داشت به صورت کتبی به اطلاع مشاور برساند. مشاور نیز باید نظر خود را اعلام نماید. در صورتی که پیمانکار همچنان به موضوع یاد شده ایراد داشته باشد می تواند موضوع را با کارفرما مطرح کند و بر اساس نظر کارفرما کار را انجام دهد.
در این صورت هرگونه مشکلی که در اجرای آن بخش از کار ایجاد شود،  به عهده پیمانکار نمی باشد.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (22, 2, 22, 'ترتيب گردش مدارك ، نقشه ها و ابلاغ دستور كارها', 'الف ) تمام نقشه ها ، مشخصات ، دستورالعملها و استاندارهاي فني كه داراي مهر و امضاي مهندس مشاور است ، به تعداد نسخه هاي درج شده در اسناد و مدارك پيمان و در صورتي كه در اسناد و مدارك پيمان تعداد نسخه معين نشده باشد ، در دو نسخه ، بدون دريافت هزينه ، در اختيار پيمانكار قرار مي گيرد . در صورت نياز پيمانكار ، نسخه هاي اضافي به هزينه او تكثير مي شود .
پيمانكار بايد يك نسخه از نقشه ها و مشخصات ، با آخرين تغييرات آنها را هميشه در كارگاه نگه داري كند ، تا در صورت لزوم ، به منظور بازرسي كارها در اختيار مهندسين مشاور ، كارفرما يا نمايندگان آنها قرار گيرد. نسخه اصل نقشه ها و مدارك ، تا پايان كار نزد مهندس مشاور باقي مي ماند .
ب) پيمانكار موظف است كه پيش از آغاز هر قسمت از كار ، تمام نقشه ها ، دستورالعملها و ديگر اسناد و مدارك فني مربوط به آن قسمت با دقت مطالعه  كند و اندازه درج شده در نقشه ها را كنترل نمايد ، به نحوي كه هيچ گونه ابهامي ز نظر چگونگي اجراي كار براي خود و كاركنانش باقي نماند . به طور كلي ، كمبود نقشه براي هر قسمت از كار هرگز از تعهدات پيمانكار مبني بر اجراي كامل كار نمي كاهد . در صورت مشاهده اشتباه در اندازه ها يا هرگونه ابهام يا كسري در مدارك ، نقشه ها و دستورالعملها ، پيمانكار بايد به موقع رفع نقض آنها را از مهندس مشاور درخواست كند . مهندس مشاور موظف است كه با توجه به برنامه زماني اجراي كار ، براي تكميل نقشه ها و ابلاغ به پيمانكار اقدام كند.
ج) هرگاه پيمانكار در مورد درستي نقشه ها و محاسبات يا دستور كارها ، يا مشخصات مصالح و تجهيزاتي كه بنا به دستور كارفرما از منابع معيني تحصيل مي شود ايرادي داشته باشد ، بايد با توجه به برنامه زماني تفصيلي ، مراتب را با ذكر دليل به اطلاع مهندس مشاور برساند . در صورتي كه مشاور ، درستي مدارك پيشگفته را تائيد كند ، ولي پيمانكار همچنان نسبت به آنها ايراد داشته باشد ، پيمانكار بايد موضوع را به كارفرما منعكس كند و پس از دريافت نظر كارفرما ، طبق نظر انجام دهد .در چنين حالتي ، پيمانكار فقط مسئول اجراي درست كار است . و در مورد صحت نقشه ها ، مشخصات ، محاسبات و دستور كار هاي مربوط ، مسئوليتي ندارد . هزينه رفع عيب و نقص در چنين مواردي به عهده پيمانكار نمي باشد .
د) پيمانكار ، نقشه هاي كارگاهي را كه نقشه هاي جزئيات ساخت قطعات و قسمت هاي از كار است ، در صورت  نياز ضمن اجراي كار ، بر اساس نقشه هاي اجرايي ، مشخصات فني و دستورالعمل سازندگان ، تهيه ميكند ، و در سه نسخه ، كه يك نسخه آن قابل تكثير باشد ،‌تسليم مهندس مشاور مي نمايد . مهندس مشاور ، نقشه هاي ياد شده را پس از بررسي و اصلاح لازم ، تائيد و در يك نسخه به پيمانكار ابلاغ مي كند . نسخه قابل تكثير اين مدارك نزد مهندس مشاور نگهداري مي شود .
ه) نقشه هايي چون ساخت ، نقشه هاي كار هاي انجام شده به نحوي كه اجرا شده اند ، مي باشند و شامل تمام نقشه هاي اجرايي ، اعم از تغيير يافته يا بدون تغيير است . پيمانكار بايد نقشه هاي چون ساخت را به تدريج و طبق نظر مهندس مشاور در سه نسخه كه يك نسخه آن قابل تكثير باشد تهيه كند و براي بررسي  و تاييد ، به مهندس مشاور بدهد . مهندس مشاور يك نسخه از نقشه هاي چون ساخت تائيد شده را در اختيار پيمانكار قرار دهد .
و) پيمانكار بايد مشخصات فني ، نقشه ها و دستورالعمل هاي نصب ، راه اندازي  و بهره برداري  تجهيزاتي را كه تامين آنها به عهده اوست ، از سازنده آنها بگيرد و در دو نسخه ، به مهندس مشاور بدهد . مهندس مشاور ، بر اساس مدارك سازنده ،‌نقشه هاي اجرايي محل استقرار تجهيزات ياد شده را تهيه و براي اجرا به پيمانكار ابلاغ مي كند .
ز) مهندس مشاور ، تمام موافقت ها ، معرفي ها ، تصويبها ، اخطارها ، و دستور كارها را به صورت كتبي ، به پيمانكار ابلاغ مي كند ، و در مورد لزوم ، به نحوه پيش بيني شده در اسناد و مدارك پيمان ، به تائيد كارفرما نيز 
مي رساند و سپس به پيمانكار ابلاغ مي كند . پيمانكار ، پس از وصول دستور كارها ، مي تواند براي اصلاح آنها اظهار نظر كند . اما در هر حال ، موظف به اجراي چين دستور كارهايي است .
در موارد دستور كار شفاهي از سوي مهندس مشاور ، پيمانكار مي تواند درخواست ابلاغ كتبي آنها را بنمايد و مهندس مشاور نيز مكلف است كه دستور كارها را كتبي به پيمانكار ابلاغ نمايد . در غير اين صورت ، اين دستور كارها براي پيمانكار معتبر نيست .
مهندس مشاور يك نسخه رو نوشت از تمام نامه هاي ابلاغي ، همراه با نقشه ها ، دستور كارها و صورت جلسه ها را براي كارفرما ارسال مي كند .
ح) پيش از تحويل موقت كار طبق ماده 39 ، پيمانكار دستورالعمل هاي راه اندازي ، راهبري ، تعمير و نگه داري را همراه با نقشه هاي چون ساخت در نسخه ، كه يك نسخه آن قابل تكثيرباشد ، به مهندس مشاور مي دهد . مدارك ياد شده بايد به نحوي باشد كه راهبري ، تعمير و نگه داري تمام قسمت هاي موضوع پيمان به سهولت انجام شود  در صورتي كه در اسناد و مدارك پيمان ، تعداد نسخه يا مشخصات ويژه اي براي مدارك موضوع اين بند تعيين شده باشد ، طبق آن عمل نمايد .', '1- موقعیت تاسیسات زیربنایی موجود مانند برق، گاز، مخابرات، آب، در انساد و مدارک پیمان ذکر شود.
2- بر اساس ماده 23 شرایط عمومی پیمان فقط در صورتی که به موقعیت تاسیسات زیر بنایی در اسناد و مدارک پیمان یا بعدها در حین انجام پیمان به اطلاع پیمانکار رسیده باشد و پیمانکار نسبت به تخریب این تاسیسات کند، باید به هزینه خود موارد تخریب شده را اصلاح نماید.
3- در صورتی که پیمانکار نسبت به اصلاح مواردی که باعث تخریب آن ها شده است، اقدام نکند، کارفرما می تواند برای رفع نقص و خسارت اقدام کند و هزینه آن بعلاوه 15 درصد به حساب بدهی پیمانکار منظور کند و پیمانکار حق اعتراضی به این موضوع را ندارد.
3- در صورتی که پیمانکار به صورت کتبی از کارفرما بخواهد که محل تاسیسات زیر بنایی را اعلام کند و کارفرما به این موضوع بی توجهی کند، در صورتی که موضوع یاد شده بیش از حد معمول به طول انجامد، پیمانکار می تواند بر اساس ماده 49 شرایط عمومی پیمان درخواست تعلیق را داشته باشد.
4- در صورتی که بیش از سه ماه از درخواست پیمانکار بگذرد و کارفرما همچنان بی تفاوت به موضوع باشد، پیمانکار می تواند بر اساس بند د ماده 49 شرایط عمومی پیمان درخواست خاتمه پیمان را کند. در صورت امتناع کارفرما در ابلاغ خاتمه پیمان، پیمانکار می تواند از طریق مراجع رفع حل اختلاف اقدام کند.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (23, 2, 23, 'حفاظت تاسيسات زير بنايي و تغيير وضع آنها', 'پيمانكار بايد عمليات موضوع پيمان را به نحوي اجرا كند كه به تاسيسات زير بنايي موجود در كارگاه ، مانند خطوط آب ، برق ، گاز ، مخابرات و مانند اينها ، آسيبي وارد نشود . هرگاه در اثر عمل پيمانكار ، به تاسيسات ياد شده صدماتي وارد شود، پيمانكار متعهد است كه هزينه ترميم و برقراري مجدد آنها را بپردازد . هرگاه پيمانكار نسبت به جبران خسارت وارد شده اقدام لازم و فوري به عمل نياورد ، كارفرما مي تواند به هر طريق كه مصلحت بداند ، براي رفع نقص و خسارت اقدام كند و هزينه آن را به اضافه 15 درصد به حساب بدهي پيمانكار منظور نمايد . پيمانكار ، از اين بابت ، حق هيچگونه اعتراضي ندارد.
در صورتي كه موقعيت تاسيسات زيرزميني در اسناد و مدارك پيمان مشخص نشده باشد ، پيمانكار بايد با توجه به برنامه زماني اجراي كار ، تعيين وضعيت آنها را از مهندس مشاور استعلام كند و بعد از اعلام نظر مهندس مشاور ، براي عمليات حفاري اقدام نمايد . بدين ترتيب ، مسئوليت پيمانكار در مورد بروز هر نوع حادثه و پرداخت خسارت و هزينه هاي پيشگفته در مورد تاسيسات زيرزميني ، منوط به آن است كه نوع ، محل يا مسير تاسيسات مزبور به اطلاع پيمانكار رسيده يا در اسناد و مدارك پيمان مشخص شده باشد .
هرگاه انجام عمليات موضوع پيمان ، تغيير وضع تاسيسات ياد شده را ايجاب نمايد ، پيمانكار به كارفرما اطلاع مي دهد تا سازمان هاي ذيربط  براي تغيير وضع اقدام نمايند . هزينه هاي مربوط به عمليات ياد شده ،به عهده كارفرماست .', '1- بر اساس جز 1 بند ب ماده 46 شرایط پیمان درصورتی که برای کارفرما اثبات شود پیمانکار کل پیمان را به دیگری واگذار کرده باشد، بدون طی چند هیچ پروسه ای می تواند قرارداد پیمانکار را فسخ کند.
2- پیمانکار می تواند بخش هایی از کار را به پیمانکاران جز واگذار نماید.
3- در صورتی که در اسناد و مدارک پیمان شرایط برای تایید پیمانکاران جز توسط کارفرما قید شده باشد، پیمانکار باید در انتخاب پیمانکاران جز با کارفرما هماهنگی لازم را داشته باشد. 
4- پیمانکار اصلی و پیمانکار جز در قرارداد فی مابین باید قید کنند که کارفرما مرجع داوری بین آن ها هست و نظر کارفرما برای طرفین قطعی و الزاماً لازم الا اجراست.
5- در صورت طلب پیمانکار جز از پیمانکار کل، در صورتی که پیمانکار جز از کارفرما و مشاور بخواهد با حضور نماینده پیمانکار کل که کار او را بررسی کند و در صورتی که پیمانکار جز طلب کار شد و پیمانکار کل از پرداخت تعهدات خودداری کرد، کارفرما می تواند از محل مطالبات پیمانکار کل، مطالبات پیمانکار جز را پرداخت کند.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (24, 2, 24, 'واگذاري ، پيمانكاران جزء', 'الف) پيمانكار حق واگذاري پيمان به ديگري را ندارد .
ب) پيمانكار مي تواند به منظور تسهيل و تسريع در اجراي قسمت يا قسمتهايي از عمليات موضوع پيمان ، پيمانهايي با پيمانكاران جزء ببند ، مشروط به آنكه آنان را از واگذاري كار به ديگران ممنوع كند . در صورتي كه در اسناد و مدارك پيمان ، كارفرما، لزوم تائيد صلاحيت پيمانكاران جزء را پيش بيني كرده باشد ، پيمانكار موظف است كه تائيد كارفرما را در اين مورد تحصيل نمايد . اين واگذاري نبايد از پيشرفت كار طبق برنامه زماني اجراي كار بكاهد ، و به هر حال به هيچ روي از مسئوليت و تعهدات پيمانكار نمي كاهد . پيمانكار مسئول تمام عملياتي است كه توسط پيمانكاران جزء يا كاركنان آنها انجام مي شود .در پيمان هاي بين پيمانكار و پيمانكار جزء بايد نوشته شود كه در صورت بروز اختلاف بين آنها ، كارفرما حق دارد ، در صورتي كه مقتضي بداند ، به مورد اختلاف رسيدگي كند . پيمانكار و پيمانكار جز نيز مي پذيرند كه نظر كارفرما در اين مورد قطعي است و تعهد مي كنند كه الزاماً آن را اجرا نمايند .
هرگاه در پرداخت مطالبات پيمانكاران جز ء با توجه به شرايط درج شده در پيمان آنها ، تاخيري روي دهد ، در صورتي كه پيمانكار جز ، تعهدات خود را بر اساس پيمان تنظيمي خود با پيمانكار كاملاً انجام داده و كار او مورد قبول و تائيد مهندس مشاور باشد ، كارفرما مي تواند بنا بر تقاضاي پيمانكار جز با حضور نماينده پيمانكار به كار او رسيدگي كند . اگر در اثر اين رسيدگي ، پيمانكار جز طلبكار باشد و از پرداخت آن خودداري كند كارفرما حق دارد طلب پيمانكار جز را براي كارهايي كه صورت وضعيت آن به پيمانكار پرداخت شده است ، از محل مطالبات پيمانكار بپردازد . در صورتي كه با اخطار كارفرما ، پيمانكار يا نماينده او براي رسيدگي حاضر نشوند كارفرما رسيدگي مي كند و به شرح پيشگفته عمل مي كند و اين عمل قطعي و غير قابل اعتراض است . هرگاه پس از فسخ پيمان ، پيمانكاران جز مطالباتي از پيمانكار داشته باشند ، مهندس مشاور و كارفرما، به شرح پيشگفته موضوع را رسيدگي مي كنند . اگر پس از رسيدگي و تهيه صورت حساب نهايي ، پيمانكار مطالباتي داشته باشد ، كارفرما مي تواند طلب پيمانكار جز را از محل مطالبات پيمانكار بپردازد.', '1- بر اساس جز 1 بند ب ماده 46 شرایط پیمان درصورتی که برای کارفرما اثبات شود پیمانکار کل پیمان را به دیگری واگذار کرده باشد، بدون طی چند هیچ پروسه ای می تواند قرارداد پیمانکار را فسخ کند.
2- پیمانکار می تواند بخش هایی از کار را به پیمانکاران جز واگذار نماید.
3- در صورتی که در اسناد و مدارک پیمان شرایط برای تایید پیمانکاران جز توسط کارفرما قید شده باشد، پیمانکار باید در انتخاب پیمانکاران جز با کارفرما هماهنگی لازم را داشته باشد. 
4- پیمانکار اصلی و پیمانکار جز در قرارداد فی مابین باید قید کنند که کارفرما مرجع داوری بین آن ها هست و نظر کارفرما برای طرفین قطعی و الزاماً لازم الا اجراست.
5- در صورت طلب پیمانکار جز از پیمانکار کل، در صورتی که پیمانکار جز از کارفرما و مشاور بخواهد با حضور نماینده پیمانکار کل که کار او را بررسی کند و در صورتی که پیمانکار جز طلب کار شد و پیمانکار کل از پرداخت تعهدات خودداری کرد، کارفرما می تواند از محل مطالبات پیمانکار کل، مطالبات پیمانکار جز را پرداخت کند.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (25, 2, 25, 'اجراي كار در شب', 'اجراي كار در شب ، در موارد زير مجاز است :
الف) در برنامه زماني تفصيلي پيش بيني شده است .
ب) هر گاه به سبب بروز تاخيرهاي از سوي پيمانكار ، انجام كار طبق تشخيص پيمانكار در مدت پيمان امكان پذير نباشد ، پيمانكار مي تواند بدون آنكه حق دريافت اضافه هزينه كار را داشته باشد با تائيد مهندس مشاور و موافقت كارفرما ، قسمتي از كار را در شب اجرا كند .
ج) هرگاه مهندس مشاور تشخيص دهد كه پيشرفت كار پيمانكار به نحوي نيست كه همه عمليات در مدت پيمان پايان يابد ، مي تواند  پس از موافقت كارفرما ، به پيمانكار دستور دهد كه قسمتي از كار را در شب اجرا كند . در اين حالت ، پيمانكار مكلف به اجراي اين دستور است و حق ادعا و يا مطالبه هيچ گونه خسارت و اضافه بها را ندارد .
د) اگر به تشخيص مهندس مشاور و تائيد كارفرما براي جبران تاخيرهايي كه ناشي از قصور پيمانكار نيست ، كار در شب نيز انجام شود ، اضافه هزينه هاي مربوط به مار در شب ، با تائيد مهندس مشاور و تصويب كارفرما ، پرداخت مي شود . در محاسبه اين هزينه ها ، به منظور تعيين اين هزينه هاي اضافي دستمزد نيروي انساني براي كار در شب ، بايد مقررات قانون كار و امور اجتماعي ملاك قرار گيرد .
پيمانكار متعهد است كه ترتيب كار را طوري دهد كه تا حد امكان ، اجراي كار در شب براي ساكنان مجاور مزاحمتي ايجاد نكند .', 'این ماده بیان‌کننده شرایط و الزامات انجام کار در ساعات شب است. بر اساس این حکم، اجرای عملیات شبانه باید با رعایت ایمنی، تأمین روشنایی مناسب و هماهنگی لازم انجام شود. هدف از این مقرره، حفظ کیفیت عملیات و جلوگیری از خطرات ناشی از کار در شرایط غیرعادی است.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (26, 2, 26, 'آثار تاريخي و اشياي عتيقه', 'هرگاه ضمن اجراي كار ، اشياي عتيقه يا آثار تاريخي و مسكوكات قديمي و مانند آن در محل كار پيدا شود ، پيمانكار متعهد است كه بي درنگ مراتب را از طريق مهندس مشاور به اطلاع كارفرما و طبق قوانين به اطلاع دستگاه هاي انتظامي برساند . كارفرما براي حفظ و نگه داري يا انتقال اشياي عتيقه ،اقدام فوري به عمل مي آورد .
پيمانكار يابد تا زمان اقدام به حفاظت از سوي كارفرما يا مقامات ذيربط ، براي حفظ و نگه داري اشياء و آثار مزبور مراقبت لازم را به عمل آورد .
هرگاه اجراي اين ماده ، موجب توقف يا تعطيل عمليات موضوع پيمان گردد ، طبق ماده 49 رفتار مي شود.', '1 نشانی کارفرما و پیمانکار در ماده 7 موافقت نامه پیمان قید می شود.
2- بر اساس ماده 1002 قانون مدنی « اقامتگاه اشخاص خقوقی مرکز عملیاتآن ها خواهد بود»');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (27, 2, 27, 'اقامتگاه قانوني', 'اقامتگاه قانوني كارفرما و پيمانكار همان است كه در موافقت نامه پيمان نوشته شده است . در صورتي كه يكي از طرفين ، محل قانوني خود را تغيير دهد ، بايد نشاني جديد خود را دست كم 15 روز پيش از تاريخ تغيير ، به طرف ديگر اطلاع دهد ، تا وقتي كه نشاني جديد به طرف ديگر اعلام نشده است ، مكاتبات به نشاني قبلي ارسال مي شود و دريافت تلقي مي گردد .', '1- بر اساس بند ج ماده 4 موافقت نامه پیمان: تاریخ شروع به کار، تاریخ نخستین صورت مججلس کارگاه است که پس از مبادله پیمان،تنظیم می شود.
2- تعهدات کارفرما در شروع پیمان:
استرداد ضمانت نامه بانکی شرکت در مناقصه به پیمانکار
امضای پیمان در مدت اعتبار پیشنهادات
ابلاغ نسخه ثانی به پیمانکار
تعیین تاریخ تحویل کار گاه حداکثر 30 روز از تاریخ ابلاغ (مبادله) پیمان
تحویل کار بدون معارض به پیمانکار
3- تعهدات پیمانکار در شروع پیمان:
تهیه و تسلیم ضمنات نامه بانکی انجام حسن تعهدات برابر ماده 34 شرایط عمومی پیمان
امضای پیمان و تحویل نسخه های امضا شده به کارفرما
حضور در محل کارگاه (اجرای کار) جهت تحویل گرفتن کارگاه
اگر پیمانکار ضمانت نامه بانکی موضوع تعهدات ماده 34 شرایط عمومی پیمان را تحویل کارفرما ندهد و یا از امضای قرارداد امتناع کند، این امر حاکی از انصراف پیمانکار از انعقاد قرارداد است و کارفرما می تواند ضمانت نامه شرکت در مناقصه را ضبط و مناقصه را تجدید کند 1- بر اساس بند ب ماده 12 شرایط عمومی پیمان: کارگاه، محل یا محل‌هایی است که عملیات موضوع پیمان در آن اجرا می‌شود یا به منظور اجرای پیمان، با اجازه کارفرما از آن استفاده می‌کنند. کارگاه‌ها یا کارخانه‌های تولیدی خارج از محل‌ها و زمین‌های تحویلی کارفرما، که به منظور ساخت تجهیزات یا قطعاتی که در کار نصب خواهد شد مورد استفاده قرار می‌گیرد جزء کارگاه به شمار نمی‌آید.
2- کارگاه دارای دو مشخصه اصلی است:
محل یا محل هایی که عملیات موضوع پیمان در آن اجرا می شود.
محل یا محل هایی که به منظور اجرای پیمان، به اذن کارفرما از آن استفاده می شود.

پس معیار کارگاه، تحویل آن توسط کارفرما است به پیمانکار است. چه برای اجرای عملیات موضوع پیمان باشد و چه برای استفاده در جهت اهداف موضوع پیمان.
3- تعهدات پیمانکار نسبت به کارگاه در ماده 21 شرایط عمومی پیمان تشریح شده است. 
4- در صورت مجلس تحویل کارگاه باید حدود و موقعیت زمین ها و محل هایی که در آن ها موضوع پیمان انجام می گیرد نشانه گذاری شود  و محل منابع تهیه مصالحی که باید در کارگاه تولید گردد، درج شود. تا بعدها در صورت به وجود آمدن اختلاف بین کارفرما و پیمانکار به آن رجوع شود.
5- با توجه به توضیحات بند ب ماده 28 شرایط عمومی پیمان کارگاه می تواند به صورت یکجا یا تدریجی به پیمانکار تحویل داده شود. این مورد می بایستی از قبل به اطلاع پیمانکار برسد تا وی در برنامه زمانبندی تفصیلی موضوع یاد شده را پیشبینی کند 6- از تعهدات کارفرما تحویل کارگاه بدون معارض می باشد. در صورتی که در محل تحویل کارگاه پیمانکار معارض پیدا کند و این امر موجب توقف کامل یا بخشی از کار شود آن قسمت از کار که متوقف شده شامل تعلیق می گردد ومطابق ماده 49 شرایط عمومی پیمان رفتار می شود.
7- بر اساس ماده 49 شرایط عمومی پیمان تعلیق کارگاه نباید بیش از سه ماه باشد و در صورت تعلیق کارگاه بیش از سه ماه در صورت عدم موافقت پیمانکار با ادامه تعلیق (به مدت سه ماه دیگر)، پیمان خاتمه داده می شود. 
8- هرگاه مدت تاخیر در تحویل کارگاه 30 درصد مدت پیمان یا 6 ماه، هرکدام که کمتر است بیشتر باشد، حقوقی به شرح ذیل به پیمانکار تعلق می گیرد:
در صورتی که آن بخش از کار کمتر از 25 درصد پیمان باشد پیمانکار با اطلاع قبلی 15 روزه آن بخش از کار را از تعهد خود خارج می کند. بر اساس بند د ماده 28 در صورتی که بخشی از ککار از تعهد پیمانکار حذف گردد، تضمین انجام تعهدات پیمانکار (موضوع ماده 34 ) نیز به همان نسبت کاهش میابد.
اگر مبلغ کارهایی که دارای معارض است بیش از 25 درصد مبلغ پیمان باشد، پیمانکار حق دارد به استناد ماده 48 شرایط عموم یپیمان درخواست خاتمه پیمان را به کارفرما بدهد.
9- بر اساس بند ب ماده 28 شرایط عمومی پیمان در صورتی که پیمانکار حداکثر تا 30 روز از مبادله پیمان نسبت به تحویل کارگاه خودداری کند، کارفرما می تواند بر اساس بند الف ماده 46 پیمان پیمان را فسخ کند.10- نحوه پرداخت خسارت تاخیر در تحویل کارگاه توسط کارفرما:

الف) اگر کارفرما بیش از یک ماه  تا 30 درصد مدت پیمان یا 6 ماه هر کدام که کمتر بود، هیچ بخش از کارگاه را به پیمانکار تحویل ندهد، ماهانه معادل 2.5 درصد متوسط کارکرد فرضی ماهانه را به پیمانکار پرداخت می کند.

ب) اگر کارفرما بیش از یک ماه  تا 30 درصد مدت پیمان یا 6 ماه هر کدام که کمتر بود، بخشهایی از کارگاه را به پیمانکار تحویل ندهد، ماهانه معادل 7.5 درصد متوسط کارکرد فرضی ماهانه بخش هایی که در آن ها تاخیر انجام شده است را به پیمانکار پرداخت می کند.

در صورتی که کارفرما به پیمانکار تعلیق پیمان را ابلاغ کند، کارفرما می بایست معادل 10درصد کارکرد فرضی ماهانه (در صورتی که در شرایط خصوصی پیمان مقدار دیگری پیش بینی نشده باشد) را به پیمانکار پرداخت کند...');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (28, 3, 28, 'تحويل كارگاه', 'الف ) كارفرما متعهد است كه كارگاه را بي عوض و بدون معارض تحويل پيمانكار دهد .
اجراي كار در زمينها و محل هاي تحويلي ، مستلزم اخذ پروانه يا پرداخت حقوقي از قبيل عوارض شهرداري ، حق ريشه و مستحدثات و مانند اينها باشد ، كارفرما متعهد است به تحصيل پروانه ساختمان و پرداخت وجوه مزبور است .
تبصره 1.اگر در اسناد و مدارك پيمان ، تامين تمام يا قسمتي از زمين مورد نياز براي تجهيز كارگاه به عهده پيمانكار گذاشته شده باشد ، طبق شرايط پيش بيني شده در پيمان عمل مي شود .
تبصره 2. در صورتي كه محل تحويل شده به پيمانكار معارض پيدا كند و موجب توقف اجراي تمام يا قسمتي از كار شود ، آن قسمت از كار كه متوقف شده است ، مشمول تعليق مي گردد و طبق ماده 49 رفتار مي شود .
ب) كارفرما بعد از مبادله پيمان ، تاريخ تحويل كارگاه را كه نبايد بيشتر از 30 روز از تاريخ مبادله  پيمان باشد ، به پيمانكار اعلام مي كند . پيمانكار بايد در تاريخ تعيين شده در محل كار حاضر شود و طي صورت جلسه هايي ، اقدام به تحويل گرفتن كارگاه بنمايد . در صورتي كه حداكثر 30 روز از تاريخ تعيين شده براي تحويل گرفتن كارگاه حاضر نشود ، كارفرما حق دارد كه طبق ماده 46 ، پيمان را فسخ كند .
در صورت جلسه هاي تحويل كارگاه بايد حدود و موقعيت زمينها و محل هايي كه در آنها موضوع پيمان اجرا 
مي شود و نقاط نشانه با مشخصات آنها ، محور عمليات و محل منابع تهيه مصالحي كه بايد در كارگاه توليد گردد ، درج شود .
اگر تحويل كارگاه به طور يكجا ميسر نباشد كارفرما بايد كارگاه را به ترتيبي تحويل دهد كه پيمانكار بتواند عمليات موضوع پيمان را طبق برنامه زماني تفصيلي انجام دهد . در اين حالت نيز مهلت كارفرما براي تحويل دست كم اولين قسمت كارگاه كه براي تجهيز كارگاه و شروع عمليات موضوع پيمان لازم است حداكثر 30 روز است .
ج) هرگاه كارفرما نتواند كارگاه را به ترتيبي تحويل دهد كه پيمانكار بتواند كار را طبق برنامه زماني تفصيلي انجام دهد ، و مدت تاخير در تحويل كارگاه بيش از يك ماه شود ، كارفرما به منظور جبران خسارت تاخير در تحويل كارگاه ، هزينه هاي اضافي ايجاد شده براي پيمانكار را كه طبق رابطه زير محاسبه مي شود پرداخت مي كند ، مشروط بر اينكه با تائيد مهندس مشاور ، پيمانكار در محل هاي تحويل شده تاخير غير مجاز نداشته باشد .
اگر در مدت تاخير از 30 درصد مدت پيمان يا 6 ماه ، هر كدام كه كمتر است بيشتر شود ، حقوقي به پيمانكار تعلق مي گيرد ، بدين ترتيب كه اگر مبلغ كارهاي پيش بيني شده در محل هاي تحويل نشده تا 25 درصد مبلغ اوليه پيمان باشد ، پيمانكار مي تواند با اطلاع قبلي 15 روزه آن قسمت از كار را از تعهدات خود حذف كند ولي اگر اين مبلغ بيشتر از 25 درصد مبلغ اوليه پيمان باشد ، در صورت اعلام خاتمه پيمان از سوي پيمانكار ، پيمان خاتمه و طبق ماده 48 عمل مي شود . هرگاه پيمانكار در محلهايي كه در تحويل آنها بيش از مدت پيشگفته تاخير شده است ، كار اجرايي را شروع نمايد ، حق حذف تعهدات در آن قسمت از كار را از خود سلب مي نمايد .
تبصره : اگر كارفرما نتواند هيچ قسمت از كارگاه را به پيمانكار تحويل دهد ، براي تاخير بيش از يك ماه تا 30 درصد تا مدت پيمان يا 6 ماه ، هر كدام كه كمتر است ، نسبت به تاريخ مبادله پيمان ، ماهانه معادل مبلغ 5/2 درصد متوسط كاركرد فرضي ماهانه را به پيمانكار پرداخت مي كند . اگر پيمانكار پس از انقضاي 30 درصد مدت پيمان يا 6 ماه ، هر كدام كه كمتر است ، مايل به ادامه يا اجراي كار نباشد ، با اعلام او ، قرارداد طبق ماده 48 خاتمه مي يابد و پيمانكار و هيچ گونه دعاوي ديگري نمي تواند مطرح نمايد .
خسارت تاخير در تحويل تمام يا قسمتي از كارگاه ، براي مدت مازاد بر يك ماه ، حداكثر تا 30 درصد مدت پيمان يا 6 ماه ، هر كدام كه متر است ، قابل پرداخت است .
د) در مواردي كه به استناد اين ماده ، قسمتي از تعهدات پيمانكار حذف شود ، تضمين انجام تعهدات پيمانكار نيز به تناسب كاهش داده مي شود .
ه) پيمانكار نمي تواند جز آنچه طبق نقشها و دستور كارهاست ، در زمينها و محل هاي متعلق به كارفرما يا ملك غير كه از طرف كارفرما به پيمانكار تحويل شده است ، اقدام به احداث بنا يا ساختمان كند . اگر در اثر اجراي كار در ملك غير كه از طرف كارفرما تحويل شده است ، صاحب ملك اقامه دعوا و درخواست خسارت و جلوگيري و توقف كار نمايد ، طرف ادعا كارفرماست و پيمانكار هيچ گونه مسئوليت و تعهدي در اين مورد ندارد .
و) در صورتي كه طبق اسناد و مدارك پيمان ، تامين تمام يا قسمتي از زمين مورد نياز تجهيز كارگاه به عهده پيمانكار باشد يا پيمانكار بخواهد طبق صلاحديد خود از محلهايي خارج از محل هاي تحويلي كارفرما براي تجهيز كارگاه استفاده كند ، بايد موقعيت آنها را به تائيد كارفرما برساند . در اين حالت ، مسئوليت هر نوع ادعا و طلب خسارت از سوي صاحب ملك به عهده پيمانكار است و كارفرما در اين موارد مسئوليتي ندارد .
هرگاه پيمانكار محل هاي مورد نياز تجهيز كارگاه را به صورت اجاره اي در اختيار بگيرد ، بايد اجاره نامه آنها ، امكان انتقال مورد اجاره را به كارفرما پيش بيني كند .', 'این ماده بیان‌کننده فرآیند تحویل کارگاه به پیمانکار برای آغاز عملیات اجرایی است. بر اساس این حکم، کارفرما موظف است محل اجرای کار را مطابق شرایط پیمان در اختیار پیمانکار قرار دهد و پیمانکار نیز مسئولیت حفاظت و استفاده صحیح از کارگاه را بر عهده می‌گیرد. هدف از این مقرره، مشخص کردن زمان و حدود مسئولیت طرفین در شروع پروژه است.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (29, 3, 29, 'تغيير مقادير كار، قيمت هاي جديد ، تعديل نرخ پيمان', 'الف)در ضمن اجراي كار، ممكن است مقادير درج شده در فهرست بها و مقادير منضم به پيمان تغيير كند . تغير مقادير به وسيله مهندس مشاور محاسبه مي شود و پس از تصويب كارفرما به پيمانكار ابلاغ مي شود . پيمانكار با دريافت ابلاغ تغيير مقادير كار ، موظف به انجام با نرخ پيمان است ، به شرط آنكه مبلغ ناشي از تغيير مقادير كار ، از حدود تعيين شده در زير بيشتر نشود .
افزايش مقادير بايد در چارچوب موضوع پيمان به پيمانكار ابلاغ شود . جمع مبلغ مربوط به افزايش مقادير و مبلغ كار هاي با قيمت جديد ( موضوع بند ج ) نبايد از 25 درصد مبلغ اوليه پيمان بيشتر شود .
تبصره : اگر نرخ پيمان مشمول تعديل آحاد بها باشد ، براي محاسبه افزايش مبلغ پيمان به سبب قيمت هاي جديد ، ابتدا قيمت هاي جديد به مبناي نرخ پيمان تبديل مي شود و سپس ملاك محاسبه قرار مي گيرد .
جمع مبلغ مربوط  به كاهش مقادير و حذف آنها نبايد از 25 درصد مبلغ اوليه پيمان بيشتر شود. اگر اين مبلغ ، از حد تعيين شده بيشتر شود و پيمانكار با اتمام كار با نرخ پيمان موافق باشد ، عمليات موضوع پيمان در چارچوب پيمان انجام مي شود . ولي در صورتي كه پيمانكار مايل به اتمام كار نباشد ، پيمان طبق ماده 48 خاتمه داده مي شود .
تبصره 1- در صورت حذف قسمتهايي از كار به استناد بند ج ماده 28 ، براي تعيين حد افزايش يا كاهش مقادير طبق بند هاي 1و2 ، به جاي مبلغ اوليه پيمان ، مبلغ اوليه پيمان پس از كسر مبلغ كار هاي حذف شده به وسيله پيمانكار ، ملاك قرار مي گيرد .
تبصره 2. اضافه يا كاهش مقادير كار طبق مفاد بند هاي (الف-1) و (الف-2) اين ماده تا 10 درصد با دستور مهندس مشاور عمل مي شود ، ولي اضافه بر آن با تصويب كارفرما قابل اجرا است .
ب)در صورتي كه پس از تكميل كار و تصويب صورت و وضعيت قطعي مشخص شود ، مقادير كار بدون آنكه از سوي كارفرما كم شده باشد ، نسبت به مقادير منضم به پيمان كاهشي بيش از حد تعيين شده در بند ( الف-2) داشته باشد ، در اين حالت نيز نرخ پيمان ملاك عمل است .
ج) اگر در چارچوب موضوع پيمان ، كارهايي به پيمانكار ابلاغ كارهايي به پيمانكار ابلاغ شود  كه براي آنها قيمت و مقدار در فهرست بها و مقادير منضم به پيمان پيش بيني نشده است ، پيمانكار بايد بي درنگ پس از دريافت ابلاغ مهندس مشاور ، قيمت پيشنهادي خود را براي اجراي كار هاي ياد شده ، همراه با تجزيه قيمت ، به مهندس مشاور تسليم نمايد . قيمتي كه با توافق پيمانكار و مهندس مشاور تعيين مي شود و به تصويب كارفرما  برسد ، ملاك پرداخت است . قيمت هاي جديدي كه به اين صورت تعيين مي شود بايد بر حسب هزينه اجراي كار در محل اجرا محاسبه گردد . از اين رو ، تنها ضريب هزينه بالا سري پيمان به قيمتهاي جديد اعمال مي شود .
تبصره – در صورتي كه پيمان با استفاده از فهرست هاي بهاي واحد پايه منعقد شده باشد ، چگونگي تعيين قيمت جديد ، علاوه بر مفاد اين بند ،‌تابع دستورالعمل  نحوه استفاده از قيمت هاي پايه در تعيين قيمت جديد با اولويت ياد شده است .
د) جمع بهاي قيمت هاي جديد ، علاوه بر آنكه تابع سقف تعيين شده در بند الف  است ، نبايد از 10 درصد مبلغ اوليه پيمان بيشتر شود .
ه) تعديل نرخ پيمان طبق شرايط پيش بيني شده در شرايط خصوصي است', 'ددر صورتیکه طبق بندهای “ الف” و “ج” ماده 29، مبلغ پیمان تغییر کند                        .رصورتی که افزایش حجم داشتم باشیم
در صورتی که کار جدیدی ابلاغ شود.

هرگاه به دستور کارفرما یا مهندس مشاور، نقشه‌های اجرایی یا مشخصات فنی تغییر اساسی کند.

هرگاه کارفرما در تحویل کارگاه، ابلاغ دستور کارها یا نقشه‌ها و تحویل مصالحی که تهیه آن‌‌‌ها به عهده اوست، تأخیر کند. تأخیر در ابلاغ دستور کارها و نقشه‌ها به شرطی مشمول این بند است که پیمانکار با توجه به برنامه زمانی تفصیلی آن‌‌‌ها را از مهندس مشاور درخواست کرده باشد.
به طور مثال نقشه پلان یک ساختمان تغییر کند یا مسیر خط انتقال یک لوله به طور کامل عوض شود..');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (30, 3, 30, 'تغيير مدت پيمان', 'الف) در صورت وقوع هر يك از موارد زير كه موجب افزايش مدت اجراي كار شود ، پيمانكار
مي تواند درخواست تمديد مدت پيمان را بنمايد . پيمانكار درخواست تمديد مدت پيمان را با ارائه محاسبات و دلايل توجيهي ، به مهندس مشاور تسليم مي كند و مهندس مشاور پس از بررسي و تائيد ، مراتب را براي اتخاذ تصميم به كارفرما گزارش مي كند و سپس نتيجه تصميم كارفرما را به پيمانكار ابلاغ مي نمايد .
در صورتي كه بند هاي الف و ج ماده 29 ، مبلغ پيمان تغيير مي كند .
هرگاه به دستور كارفرما يا مهندس مشاور نقشه هاي اجرايي يا مشخصات فني تغيير اساسي كند .
هرگاه كارفرما در تحويل كارگاه ، ابلاغ دستور كارها يا نقشه و تحويل مصالحي كه تهيه آنها به عهده اوست تاخير كند . تاخير ابلاغ دستور كارها و نقشه ها به شرطي مشمول اين بند است كه پيمانكار با توجه به برنامه زماني تفصيلي ، آنها را از مهندس مشاور درخواست كرده باشد .
اگر در تحويل مصالحي كه فروش آنها لزوماً بايد با حواله كارفرما صورت گيرد تاخير ايجاد شود به شرطي كه پيمانكار با توجه به برنامه زماني تفصيلي براي تهيه آنها به موقع اقدام كرده باشد .
در موارد حوادث قهري و همچنين در موارد مربوط به كشف اشياي عتيقه و آثار تاريخي به در مواد 26 و 43 پيش بيني شده است .
هرگاه محدوديت براي ورود مصالح و تجهيزات طبق بند (د) ماده 20 پيش آيد .
در صورتي كه طبق ماده 49 به حالت تعليق درآيد .
در صورتي كه قوانين و مقررات جديدي وضع شود كه در تغيير مدت اجراي كار موثر باشد .
هرگاه كارفرما نتواند تعهدات مالي خود را در موعد هاي درج شده در اسناد و مدارك پيمان انجام دهد .
10-موارد ديگري كه به تشخيص كارفرما خارج از قصور پيمانكار باشد .
ب) اگر وقوع برخي از موارد درج شده در بند الف موجب كاهش مدت پيمان شود ، مهندس مشاور با كسب نظر پيمانكار ، كاهش مدت پيمان را تعيين مي كند . و مراتب را براي اتخاذ تصميم به كارفرما گزارش مي نمايد و سپس نتيجه تصميم كارفرما را به پيمانكار ابلاغ مي كند .
ج) در پايان مدت اوليه پيمان يا هر تمديد مدت پيمان ، اگر كار به اتمام نرسيده باشد ، مهندس مشاور با كسب نظر پيمانكار و با توجه به موارد تعيين شده در بند الف علل تاخير كار را بررسي مي كند و ميزان مدت مجاز و غير مجاز آن را با توافق پيمانكار تعيين مي نمايد و نتيجه كار را به كارفرما گزارش مي دهد و سپس نظر كارفرما را در مورد ميزان مجاز يا غير مجاز تاخير كار به پيمانكار اعلام مي كند و معادل مدت تاخير مجاز ، مدت پيمان را تمديد مي نمايد .
د)در اجراي مفاد اين ماده براي تمديد مدت پيمان ، تاخير هاي هم زمان ناشي از عوامل مختلف درج شده در بند الف ، فقط يك بار محاسبه مي شود .
ه) در اجراي مفاد اين ماده ، اگر پيمانكار با مهندس مشاور توافق نداشته باشد يا نسبت به تصميم كارفرما معترض باشد ، طبق نظر كارفرما عمل مي شود و پيمانكار مي تواند بر اساس ماده 53 براي حل مسئله اقدام نمايد .', 'این ماده بیان‌کننده شرایط و نحوه تغییر مدت پیمان در صورت ایجاد عوامل مؤثر بر زمان اجرای پروژه است. بر اساس این حکم، مدت پیمان تنها در موارد پیش‌بینی‌شده در قرارداد و پس از بررسی و تأیید عوامل ذی‌ربط قابل تغییر است. هدف از این مقرره، مدیریت صحیح زمان پروژه و جلوگیری از اختلافات ناشی از تأخیرات می‌باشد.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (31, 3, 31, 'مديرت اجرا', 'كارفرما مي تواند قسمتي از اختيارات خود را به شخص حقوقي ، كه مدير طرح ناميده مي شود ، واگذار نمايد . كارفرما مدير طرح را با تعيين حدود اختيارات واگذار شده به پيمانكار معرفي مي نمايد . تمام تصميم گيري هاي مدير طرح در چارچوب اختيارات واگذار شده ، در حكم تصميم كارفرما مي باشد .', 'این ماده بیان‌کننده نقش و اختیارات مدیر طرح در مدیریت اجرای پیمان است. بر اساس این حکم، مدیر طرح از سوی کارفرما برای انجام امور مدیریتی و هماهنگی پروژه معرفی می‌شود و اختیارات وی در حدود اسناد پیمان خواهد بود. هدف از این مقرره، ایجاد مدیریت منسجم و تسهیل ارتباطات اجرایی پروژه است.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (32, 3, 32, 'نظارت بر اجراي كار', 'الف ) عمليات اجراي پيمانكار ، هميشه بايد زير نظر و با اطلاع مهندس مشاور انجام شود ، نظارتي كه طرف كارفرما و مهندس مشاور در اجراي كارها به عمل مي آيد . به هيچ روي ، از ميزان مسئوليت پيمانكار نمي كاهد .
نظارت مستقيم در كار پيمانكار ، در محدوده كارگاه و در موارد خاص ( براي ساخت قطعات و تجهيزات ) در خارج از كارگاه انجام مي شود .  در هر حال ، پيمانكار بايد گزارش پيشرفت اقدامهايي را كه در خارج از كارگاه به منظور انجام تعهدات پيمان انجام مي دهد ، به مهندس مشاور تسليم نمايد .
ب) مهندس مشاور ، تنها مرجع فني پيمانكار براي اجراي موضوع پيمان از سوي كارفرماست .
هرگاه تغييرات ، اظهار نظر هاي فني و اصلاحات مورد نظر پيمانكاران ، سازندگان و بازرسان فني ،‌پس از هماهنگي با مهندس مشاور انجام مي گيرد . توسط وي به پيمانكار ابلاغ مي شود . مواردي كه مهندس مشاور ، موظف به كسب مجوز از كارفرما ، براي انجام وظايف نظارت است ، در اسناد و مدارك پيمان تعيين شده است .
ج) مهندس مشاور به منظور اطمينان از صحت اجراي كار ، اقدام آزمايش مصالح يا كارهاي انجام يافته مي كند . هزينه انجام آزمايشها بر عهده كارفرماست ، مگر آنكه در اسناد و مدارك پيمان ترتيب ديگري هم پيش بيني شده باشد . هرگاه نتايج اين آزمايشها با آنچه كه در مدارك فني تعيين شده است تطبيق نكند ، پيمانكار متعهد است كه مصالح و كارها را طبق دستور مهندس مشاور اصلاح كند . هزينه انجام اين اصلاحات به عهده پيمانكار است ، مگر آنكه نقص موجود مربوط به مدارك فني باشد .
پيمانكار موظف است كه براي نمونه برداري از مصالح يا انجام هر نوع آزمايشي ، تعداد لازم كارگر به صورت موردي و موقت ، به طور رايگان در اختيار مهندس مشاور بگذارد .
د) در صورتي كه مهندس مشاور مواردي از عدم رعايت مشخصات فني ، نقشه ها و مدارك ديگر فني پيمان را در اجراي كارها مشاهده كند ، با ارسال اخطاريه اي اصلاح كار هاي معيوب را در مدت مناسبي كه با توجه به حجم و نوع كار تعيين مي نمايد از پيمانكار مي خواهد . اگر پس از مهلت تعيين شده پيمانكار نسبت به اصلاح ، كارها اقدام نكند ، كارفرما مي تواند خودش كارهاي معيوب را اصلاح نمايد و هزينه هاي مربوط را به اضافه 15 درصد از مطالبات پيمانكار كسر نمايد . در صورتي كه عدم توجه به اخطار مهندس مشاور براي اصلاح هر كار معيوب از سوي پيمانكار تكرار شود ، كارفرما مي تواند پيمان را طبق ماده 46 فسخ نمايد .
ه) كارفرما در مدت اجراي پيمان ، هر موقع كه لازم بداند ، توسط نمايندگان خود عمليات پيمانكار را بازرسي مي كند .  پيمانكار موظف است كه هر نوع اطلاعات و مداركي را كه مورد نياز باشد ، در اختيار نمايندگان كارفرما بگذارد و تسهيلات لازم را براي انجام اين بازرسي ها فراهم سازد .
و)اگر كارفرما در طول مدت پيمان ، تصميم به تغيير مهندس مشاور بگيرد ، اين تصميم بايد دست كم يك ماه پيشتر به اطلاع پيمانكار برساند . پيمانكار و مهندس مشاور ، موظف هستند كه تكليف آزمايش هايي نا تمام ، صورت جلسه هاي در دست اقدام و صورت كاركرد هاي در حال رسيدگي را روشن كنند . در صورتي كه مهندس مشاور به شرح پيشگفته عمل نكند ، كارفرما مستقيماً به جاي مهندس مشاور تكليف كار هاي ناتمام را روشن مي كند و هزينه هاي مربوط به اين اقدام را به حساب بدهي مهندس مشاور منظور مي نمايد .
اگر در زمان اعلام كارفرما مبني بر تغيير مهندس مشاور ، بخشهايي از كار توسط پيمانكار در حال اجرا باشد كه اتمام آن بخش منجر به صدور تائيديه هاي مهندس مشاور شده و اين امر موكول به زمان پس از تغيير مهندس مشاور شود ، اين گونه موارد ، بايد در طول يك هفته از تاريخ اعلام كارفرما ، از سوي پيمانكار به كارفرما منعكس شود ، تا كارفرما ترتيب لازم را براي عدم انقطاع آن بخش از كار پيمانكار و صدور به موقع تائيديه  بدهد .
كارفرما مهندس مشاور جديد را به پيمانكار معرفي ميكند و اختيارات او را طبق آنچه كه براي مهندس مشاور قبلي تعيين شده بود ، تنفيذ يا تغييرات مربوط را به پيمانكار ابلاغ مي كند و از آن پس ، تصميم ها ، و دستورهاي مهندس مشاور جديد در چارچوب پيمان براي پيمانكار لازم الاجراست .', 'این ماده بیان‌کننده وظایف و حدود نظارت بر اجرای کار توسط مهندس مشاور و عوامل نظارتی است. بر اساس این حکم، نظارت بر عملیات اجرایی به منظور اطمینان از رعایت مشخصات فنی، کیفیت و مفاد پیمان انجام می‌شود. هدف از این مقرره، تضمین کیفیت اجرای پروژه و کنترل عملکرد پیمانکار است.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (33, 3, 33, 'مهندس ناظر', 'مهندس ناظر كه نماينده مهندس مشاور در كارگاه است وظيفه دارد كه با توجه به اسناد و مدارك پيمان ، در اجراي كار ، نظارت و مراقبت دقيق به عمل آورد و مصالح و تجهيزاتي را كه بايد به مصرف برساند ، بر اساس نقشه ها و مشخصات فني مورد رسيدگي و آزمايش قرار دهد و هرگاه عيب و نقصي در آنها يا در نحوه مهارت كاركنان يا چگونگي كار مشاهده كند ، دستور رفع آنها را به پيمانكار بدهد . همچنين هر گاه بعضي از ماشين آلات معيوب باشد به طوري كه نتوان با آنها كار كرد ، مهندس ناظر تعمير يا تعويض و يا تغيير آنها را از پيمانكار مي خواهد . با رعايت مفاد بند ب ، هرگونه دستوري كه از طرف مهندس ناظر به پيمانكار داده مي شود ، به مثابه دستور هاي داده شده توسط مهندس مشاور است . پيمانكار ملزم به اجراي آنهاست .
ب)مهندس ناظر ، به هيچ روي ،حق ندارد كه از تعهدات پيمانكار بكاهد يا موجب تمديد مدت پيمان يا پرداخت اضافي به پيمانكار شود يا هر نوع دستور تغيير كاري را صادر كند .
ج) پيمانكار مكلف است كه دستور هاي مهندس ناظر را در حدود مفاد اين ماده اجرا نمايد ، مگر در مواردي كه آنها را بر خلاف اسناد و مدارك پيمان تشخيص دهد ، كه در اين صورت ، موظف است كه موضوع را به مهندس مشاور بنويسد و كسب تكليف كند . هرگاه مهندس مشاور موضوع را فيصله ندهد ، نظر كارفرما در آن مورد قاطع مي شود .
د)با وجود نظارتي كه از طرف مهندس ناظر در اجراي كارها به عمل مي آيد ، كارفرما و مهندس مشاور حق دارد مصالح مصرفي و كارهاي انجام يافته را مورد رسيدگي قرار دهند . و اگر مشخصات آنها را مغاير نقشه ها و مشخصات فني تشخيص دهند ، پيمانكار متعهد است مصالح و كارهاي معيوب را به هزينه خود تعويض نمايد . به هر حال ، نظارت مهندس ناظر از مسئوليت هاي پيمانكار نمي كاهد و سلب حق از كارفرما و مهندس مشاور نمي كند .', 'تضمین انجام تعهدات:
1- 5 درصد مبلغ اولیه پیمان است و توسط پیمانکار در ابتدای پروژه به کارفرما تحویل داده می شود.
2- در صورتی که میزان بدهی پیمانکار از نصف کسور تضمین حسن انجام کار کمتر بود، کارفرم بی درنگ تضمین انجام تعهدات را آزاد می کند.
3- اعتبار ضمانت نامه انجام تعهدات باید یک ماه پس از تاریخ تحویل موقت موضوع پیمان معتبر باشد. تضمین حسن انجام کار:
1- از هر صورت وضعیت موقت 10 درصد به عنوان تضمین حسن انجام کار توسط کارفرما ضبط می شود.
2- نیمی از تصیمن حسن انجام کار بعد از صورت وضعیت قطعی و نیمی از آن بعد از تحویل قطی آزاد خواهد شد.
3- پیمانکار می تواند با ارائه ضمانت نامه بانکی نسبت به آزاد سازی مبالغ نقد تضمین حسن انجام کار اقدام کند. پیش پرداخت:
1- کل پیش پرداخت برابر 20 درصد مبلغ اولیه پیمان می باشد.
2- پیش پرداخت در سه قسط پرداخت می گردد:
الف- چهل درصد مبلغ پیش پرداخت، پس از تحویل کارگاه (8 درصد مبلغ اولیه پیمان)
ب- سی درصد مبلغ پیش پرداخت پس از تجهیز کارگاه بر اساس اسناد و مدارک پیمان (6 درصد مبلغ اولیه پیمان)
ج- سی درصد مبلغ پیش پرداخت پس از سی درصد پیشرفت ریالی پروژه (6 درصد مبلغ اولیه پیمان)
3- پیمانکار در عوض دریافت هر پیش پرداخت، ضمنات نامه به نفع دستگاه اجرایی را ارائه می دهد.
4- از پیش پرداخت ها هیچ گونه کسر کسورات قانونی صورت نمی گیرد.
5- از هر صورت وضعیت پیمانکار معادل درصد پرداخت شده پیش پرداخت کسر خواهد شد.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (34, 4, 34, 'تضمين انجام تعهدات', 'موقع امضاي پيمان ،براي تضمين انجام تعهدات ناشي از آن ، پيمانكار بايد ضمانت نامه اي معادل 5 درصد مبلغ اوليه پيمان صادر شده از طرف بانك مورد قبول كارفرما و طبق نمونه اي كه ضميمه اسناد مناقصه بوده است ، تسليم كارفرما كند . ضمانتنامه ياد شده بايد تا يك ماه پس از تاريخ تحويل موقت موضوع پيمان معتبر باشد . تا هنگامي كه تحويل موقت انجام نشده است ، پيمانكار مكلف است براي تمديد ضمانت نامه ياد شده اقدام نمايد . و اگر تا 15 روز پيش از انقاضاي مدت اعتبار ضمانتنامه پيمانكار موجبات تمديد آن را فراهم نكرده است كارفرما حق دارد كه مبلغ ضمانتنامه را از بانك ضامن دريافت كند و وجه آن را به جاي ضمانتنامه ، به رسم وثيقه نزد خود نگه دارد . كارفرما تضمين انجام تعهدات را پس از تصويب صورت مجلس تحويل موقت ، با توجه به تبصره 1 اين ماده آزاد است .
تبصره 1.حداكثر تا يك ماه بعد از تحويل موقت ، آخرين صورت وضعيت موقت طبق ماده 37، بدون منظور داشتن مصالح پاي كار تنظيم مي شود . هرگاه بر اساس اين صورت وضعيت ، پيمانكار بدهكار نباشد يا جمع بدهي او نصف كسور تضمين حسن انجام كار كمتر باشد ضمانت نامه  انجام تعهدات بي درنگ آزاد مي شود. ولي هرگاه ميزان بدهي پيمانكار ، از نصف كسور تضمين حسن انجام كار بيشتر باشد ، ضمانت نامه انجام تعهدات بر حسب مورد طبق شرايط تعيين شده در ماده 40 يا 52 آزاد مي شود .
تبصره 2. در صورتي كه تمام يا قسمتي از تضمين انجام تعهدات ، به صورت نقد نزد كارفرما باشد ، با رعايت مقررات ، به جاي ضمانت نامه بانكي از انواع ديگر اوراق بهادار استفاده شود ، چگونگي گرفتن تضمين و استرداد آن در هر مورد ، طبق شرايطي است كه در اين پيمان براي ضمانتنامه بانكي تعيين شده است .', 'تضمین انجام تعهدات:
1- 5 درصد مبلغ اولیه پیمان است و توسط پیمانکار در ابتدای پروژه به کارفرما تحویل داده می شود.
2- در صورتی که میزان بدهی پیمانکار از نصف کسور تضمین حسن انجام کار کمتر بود، کارفرم بی درنگ تضمین انجام تعهدات را آزاد می کند.
3- اعتبار ضمانت نامه انجام تعهدات باید یک ماه پس از تاریخ تحویل موقت موضوع پیمان معتبر باشد. تضمین حسن انجام کار:
1- از هر صورت وضعیت موقت 10 درصد به عنوان تضمین حسن انجام کار توسط کارفرما ضبط می شود.
2- نیمی از تصیمن حسن انجام کار بعد از صورت وضعیت قطعی و نیمی از آن بعد از تحویل قطی آزاد خواهد شد.
3- پیمانکار می تواند با ارائه ضمانت نامه بانکی نسبت به آزاد سازی مبالغ نقد تضمین حسن انجام کار اقدام کند. پیش پرداخت:
1- کل پیش پرداخت برابر 20 درصد مبلغ اولیه پیمان می باشد.
2- پیش پرداخت در سه قسط پرداخت می گردد:
الف- چهل درصد مبلغ پیش پرداخت، پس از تحویل کارگاه (8 درصد مبلغ اولیه پیمان)
ب- سی درصد مبلغ پیش پرداخت پس از تجهیز کارگاه بر اساس اسناد و مدارک پیمان (6 درصد مبلغ اولیه پیمان)
ج- سی درصد مبلغ پیش پرداخت پس از سی درصد پیشرفت ریالی پروژه (6 درصد مبلغ اولیه پیمان)
3- پیمانکار در عوض دریافت هر پیش پرداخت، ضمنات نامه به نفع دستگاه اجرایی را ارائه می دهد.
4- از پیش پرداخت ها هیچ گونه کسر کسورات قانونی صورت نمی گیرد.
5- از هر صورت وضعیت پیمانکار معادل درصد پرداخت شده پیش پرداخت کسر خواهد شد.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (35, 4, 35, 'تضمين حسن انجام كار', 'از مبلغ هر پرداخت به پيمانكار ،معادل 10 درصد به عنوان تضمين حسن انجام كار كسر و در حساب سپرده نزد كارفرما نگاهداري مي شود . نصف اين مبلغ پس از تصويب صورت وضعيت قطعي طبق ماده 40 و نصف ديگر پس از تحويل قطعي ، با رعايت مواد 42 و 52 ، مسترد مي گردد.
تبصره – پيمانكار مي تواند ،وجوه سپرده تضمين حسن انجام كار را طبق دستورالعمل نافذ در زمان ارجاع كار كه شماره و تاريخ آن در اسناد و مدارك پيمان درج شده است ،دريافت كند .', 'تضمین انجام تعهدات:
1- 5 درصد مبلغ اولیه پیمان است و توسط پیمانکار در ابتدای پروژه به کارفرما تحویل داده می شود.
2- در صورتی که میزان بدهی پیمانکار از نصف کسور تضمین حسن انجام کار کمتر بود، کارفرم بی درنگ تضمین انجام تعهدات را آزاد می کند.
3- اعتبار ضمانت نامه انجام تعهدات باید یک ماه پس از تاریخ تحویل موقت موضوع پیمان معتبر باشد. تضمین حسن انجام کار:
1- از هر صورت وضعیت موقت 10 درصد به عنوان تضمین حسن انجام کار توسط کارفرما ضبط می شود.
2- نیمی از تصیمن حسن انجام کار بعد از صورت وضعیت قطعی و نیمی از آن بعد از تحویل قطی آزاد خواهد شد.
3- پیمانکار می تواند با ارائه ضمانت نامه بانکی نسبت به آزاد سازی مبالغ نقد تضمین حسن انجام کار اقدام کند. پیش پرداخت:
1- کل پیش پرداخت برابر 20 درصد مبلغ اولیه پیمان می باشد.
2- پیش پرداخت در سه قسط پرداخت می گردد:
الف- چهل درصد مبلغ پیش پرداخت، پس از تحویل کارگاه (8 درصد مبلغ اولیه پیمان)
ب- سی درصد مبلغ پیش پرداخت پس از تجهیز کارگاه بر اساس اسناد و مدارک پیمان (6 درصد مبلغ اولیه پیمان)
ج- سی درصد مبلغ پیش پرداخت پس از سی درصد پیشرفت ریالی پروژه (6 درصد مبلغ اولیه پیمان)
3- پیمانکار در عوض دریافت هر پیش پرداخت، ضمنات نامه به نفع دستگاه اجرایی را ارائه می دهد.
4- از پیش پرداخت ها هیچ گونه کسر کسورات قانونی صورت نمی گیرد.
5- از هر صورت وضعیت پیمانکار معادل درصد پرداخت شده پیش پرداخت کسر خواهد شد.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (36, 4, 36, 'پيش پرداخت', 'كارفرما موافقت دارد كه به منظور تقويت بنيه مالي پيمانكار ، مبلغي به عنوان پيش پرداخت به پيمانكار پرداخت نمايد . ميزان ، روش پرداخت و چگونگي واريز پيش پرداخت و ديگر ضوابط آن ، بر اساس دستورالعمل مربوط است كه در زمان ارجاع كار نافذ بوده و شماره و تاريخ آن در اسناد و مدارك پيمان درج شده است .
پيمانكار در موعد هاي مقرر در دستورالعمل پيشگفته ، براي دريافت هر يك از اقساط پيش پرداخت ، درخواست خود را به مهندس مشاور مي نويسد . كارفرما پس از تائيد مهندس مشاور ، هر قسط پيش پرداخت را در مقابل تضمين تعيين شده در دستورالعمل ، بدون اينكه وجوهي از آن كسر شود ، پرداخت مي نمايد . مهلت پرداخت هر قسط پيش پرداخت 20 روز از تاريخ درخواست پيمانكار كه به تائيد مهندس مشاور رسيده است ، يا 10 روز از تاريخ ارائه تضمين از سوي پيمانكار ، هر كدام كه بيشتر است ، مي باشد .', 'این ماده بیان‌کننده شرایط پرداخت پیش‌پرداخت به پیمانکار برای تأمین منابع مالی اولیه اجرای کار است. بر اساس این حکم، پرداخت پیش‌پرداخت طبق مقررات پیمان و در مقابل تضمین‌های لازم انجام می‌شود. هدف از این مقرره، فراهم کردن امکان شروع و استمرار عملیات اجرایی است.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (37, 4, 37, 'پرداخت ها', 'الف)در آخر هر ماه ، پيمانكار ، وضعيت كار هاي انجام شده از شروع كار تا آن تاريخ را طبق نقشه هاي اجرايي ، دستور كارها و صورت جلسه هاست اندازه گيري مي نمايد و مقدار مصالح و تجهيزات پاي كار را تعيين مي كند ، سپس بر اساس فهرست بهاي منضم به پيمان ، مبلغ صورت وضعيت را محاسبه كرده و آنرا در آخر ماه تسليم مهندس ناظر مي نمايد . مهندس مشاور ، صورت وضعيت پيمانكار را از نظر تطبيق با اسناد و مدارك پيمان كنترل كرده و در صورت لزوم با تعيين دليل اصلاح مي نمايد و آن را در مدت حداكثر 10 روز از تاريخ دريافت از سوي مهندس ناظر براي كارفرما ارسال مي نمايد و مراتب را نيز به اطلاع پيمانكار مي رساند . كارفرما صورت وضعيت كنترل شده از سوي مهندس ناظر ، براي كارفرما ارسال مي نمايد و مراتب را نيز به اطلاع پيمانكار مي رساند . كارفرما صورت وضعيت كنترل شده از سوي مهندس مشاور را رسيدگي كرده و بعد از كسر وجوهي كه بابت صورت وضعيت هاي موقت قبلي پرداخت شده است و همچنين اعمال كسور قانوني و كسور متعلقه طبق پيمان ، باقيمانده مبلغ قابل پرداخت به پيمانكار را حداكثر ظرف 10 روز از تاريخ وصول صورت وضعيت ، با صدور چك به نام پيمانكار ، پرداخت مي كند . با پرداخت صورت وضعيت موقت ، تمام كارها و مصالح و تجهيزاتي كه در صورت وضعيت مزبور درج گرديده است متعلق به كارفرماست ، ليكن به منظور اجراي بقيه كار هاي موضوع پيمان ، به رسم امانت ، تا موقع تحويل موقت ، در اختيار پيمانكار قرار مي گيرد .
مقادير درج شده در صورت وضعيت هاي موقت و پرداخت هايي كه بابت آنها به عمل مي آيد جنبه موقت و علي الحساب دارد و هر نوع اشتباه اندازه گيري و محاسباتي و جز اينها ، در صورت وضعيت هاي بعدي يا در صورت وضعيت قطعي ،اصلاح و رفع ميشود . به منظور ايجاد امكان براي تهيه ، رسيدگي و تصويب صورت وضعيت قطعي در مهلت هاي تعيين شده در ماده 40 پيمانكار بايد ضمن اجراي كار و پس از اتمام هر يك از اجزاي آن ، نسبت به تهيه متره هاي قطعي و ارائه آنها به مهندس مشاور براي رسيدگي همراه با صورت جلسه ها و مدارك مربوط اقدام نمايد ، اين اسناد بايد در تهيه صورت وضعيت هاي موقت نيز مورد استفاده قرار مي گيرد .
تبصره 1.هر گاه به عللي صورت وضعيت ارسالي از طرف مهندس مشاور مورد تائيد كارفرما پس از وضع كسور تعيين شده در اين ماده ، تا 70 درصد مبلغ صورت وضعيتي را كه مهندس مشاور ارسال نموده است ، به عنوان علي الحساب و در مدت مقرر در اين ماده در وجه پيمانكار پرداخت مي كند و صورت وضعيت را همراه با دلايل رد آن ، براي تصحيح به مهندس مشاور بر ميگرداند ، تا پس از اعمال اصلاحات لازم در مدت حداكثر 5 روز ، دوباره به شرح ياد شده براي كارفرما اصلاح  ارسال شود و بقيه مبلغ به ترتيبي كه گفته شد به پيمانكار پرداخت گردد . در اين صورت ، مهلت پرداخت مبلغ صورت وضعيت از تاريخي شروع مي شود كه صورت وضعيت تصحيح شده تسليم كارفرماشود .
تبصره 2.هرگاه پيمانكار نسبت به صورت وضعيتي كه به شرح پيشگفته اصلاح شده است معترض باشد ، اعتراض خود را با ذكر دليل ، حداكثر ظرف يك ماه ، به كارفرما اعلام ميكند تا مورد رسيدگي  قرار گيرد .
تبصره 3. اگر پيمانكار در موعد مقرر صورت وضعيت موقت را تهيه و تسليم مهندس ناظر نكند ، مهندس مشاور با تائيد كارفرما و به هزينه پيمانكار اقدام به تهيه آن مي كند و اقدامات بعدي براي رسيدگي و پرداخت آن را به ترتيب اين ماده به عمل مي آورد . در اين حالت ، هيچ گونه مسئوليتي از نظر تاخير در پرداخت صورت وضعيت مربوط متوجه كارفرما نيست .
ب)در پيمانهايي كه مشمول تعديل آحاد بها هستند ، پس از تائيد هر صورت وضعيت موقت از سوي كارفرما ، پيمانكار صورت وضعيت تعديل آحاد بهاي آن صورت وضعيت را بر اساس آخرين شاخص هاي اعلام شده محاسبه مي نمايد و به منظور بررسي و پرداخت به نحوي كه در بند الف تعيين شده است ، براي مهندس مشاور ارسال مي كند .
تبصره – اگر به هر دليل و غير از قصور پيمانكار ، تعديل كاركرد هاي هر نيمه از سال (سه ماهه اول و دوم و سوم و چهارم )پس از سپري شدن سه ماه از آن نيمه سال ، با شاخص هاي قطعي ، پرداخت نشود ، طبق بند 9 ماده 30 عمل خواهد شد .
ج)براي پرداخت وجوه ديگري كه به وجب اسناد و مدارك پيمان به پيمانكار تعلق مي گيرد ، مهندس مشاور ، ظرف مدت 10 روز از تاريخ دريافت صورت حساب پيمانكار ، آن را رسيدگي مي كند و به كارفرما تسليم مي نمايد تا طبق بند الف براي رسيدگي و پرداخت آن اقدام شود .', 'این ماده بیان‌کننده نحوه انجام پرداخت‌های مربوط به کارهای انجام‌شده توسط پیمانکار است. بر اساس این حکم، پرداخت‌ها بر مبنای صورت وضعیت‌ها و پس از تأیید مراجع مربوط انجام می‌شود. هدف از این مقرره، تعیین روش قانونی پرداخت مطالبات پیمانکار و کنترل مالی پروژه است.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (38, 4, 38, 'پرداخت هاي ارزي', 'هرگاه طبق اسناد و مدارك پيمان پيمانكار براي بعضي از هزينه هاي اجرايي موضوع پيمان ،احتياج به ارز داشته باشد ، بدين ترتيب رفتار مي شود .
الف) اگر در اجراي بند الف ماده 17 براي استخدام متخصصان خارجي در اسناد و مدارك پيمان ، پرداخت ارز از سوي كارفرما تعهد شده باشد ، كارفرما ارز مورد نياز را در مقابل پرداخت معادل ريالي آن از سوي پيمانكار، به نرخ رسمي فروش بانك مركزي ايران در تاريخ پرداخت ، در اختيار پيمانكار قرار مي دهد ، به شرط آنكه قرارداد آنها ، قسمتي از حقوق كه هيچ گاه نبايد از 50 درصد بيشتر باشد ، به ارز پيش بيني شده باشد .
ب)براي تهيه مصالح و تجهيزاتي كه در اسناد و مدارك پيمان ،پرداخت ارز از سوي كارفرما تعهد شده است و بايد از خارج كشور وارد شود و در عمليات موضوع پيمان مصرف گرديده و در كار باقي بماند ، پيمانكار بايد طبق مشخصات تعيين شده در اسناد و مدارك پيمان و با توجه به برنامه زماني تفصيلي ، براي تهيه پروفرماي خريد مصالح و تجهيزات مورد بحث ، به طوري دست كم داراي 90 روز اعتبار باشد ، اقدام نمايد . پيمانكار بايد با مسئوليت خود ، اسناد فروشنده را از لحاظ انطباق مقادير و مشخصات آنها با اسناد و مدارك پيمان ، كنترل نمايد ،و پس از تائيد ، ظرف مدت 20 روز از تاريخ وصول آنها ، نظر كارفرما را به پيمانكار ابلاغ نمايد . اسناد مربوط به خريد مصالح و تجهيزات پيشگفته بايد به نام كارفرما صادر شود . كارفرما صادر شود . كارفرما بر اساس اسناد تائيد شده به حساب پيمانكار اقدام به گشايش اعتبار مي نمايد . پيمانكار با نظارت كارفرما ، نسبت به ترخيص مصالح و تجهيزات سفارش شده از گمرك ، به هزينه خود ، اقدام مي نمايد . پس از آنكه مصالح و تجهيزات ياد شده وارد كارگاه شد و بهاي آن به صورت كار يا مصالح و تجهيزات پاي كار در صورت وضعيتها منظور گرديد ، پرداخت هاي قبلي كه به صورت اعتبار از طرف كارفرما انجام شده است ، از طلب پيمانكار كسر مي شود .
ج) اگر در اجراي بند هاي (الف) و (ب) نرخ تسعير ارز نسبت به نرخ آن در تاريخ تسليم پيشنهاد قيمت پيمانكار تغيير كند ، در صورت افزايش نرخ ارز ، تفاوت نرخ تسعير ارز به حساب بستانكاري پيمانكار منظور مي شود . و در صورت كاهش نرخ ارز به حساب بدهي پيمانكار منظور مي گردد.
د) تعديل نرخ كارهاي موضع بند (ب) در صورت شمول تعديل به اين پيمان، تابع مقررات تعديل خاص طبق دستورالعمل آحاد بها كه در مورد اين پيمان نافذ است ، مي باشد .
ه) اگر براي خريد ماشين آلات و ابزار خاصي كه براي اجراي كار مورد نياز است و امكان تهيه آنها در داخل نيست و بايد خارج از كشور وارد شود ،از سوي كارفرما تسهيلات ارزي در اسناد و مدارك پيمان پيش بيني شده باشد ، در اين مورد ، به ترتيب پيش بيني شده عمل مي شود . پرداخت هزينه تامين ماشين آلات و ابزار موضوع اين بند ، به عهده پيمانكار ، و مالكيت آنها ، متعلق به پيمانكار است .', 'این ماده بیان‌کننده شرایط پرداخت‌های ارزی در صورت وجود تعهدات ارزی در پیمان است. بر اساس این حکم، نحوه پرداخت و تسویه مبالغ ارزی باید مطابق اسناد پیمان و مقررات مربوط انجام شود. هدف از این مقرره، شفاف‌سازی تعهدات مالی ارزی طرفین است.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (39, 4, 39, 'تحويل موقت', 'الف)پس از آنكه عمليات موضوع پيمان تكميل گرديد و كار آماده بهره برداري شد ، پيمانكار از مهندس مشاور تقاضاي تحويل موقت مي كند و نماينده خود را براي عضويت در هيات تحويل معرفي مي نمايد . مهندس مشاور ، به درخواست پيمانكار رسيدگي مي كند و در صورت تائيد ، ضمن تعيين تاريخ آمادگي كار براي تحويل موقت ، تقاضاي تشكيل هيات تحويل موقت را از كارفرما مي نمايد. كارفرما به گونه اي ترتيب كار را فراهم مي كند كه هيات تحويل ، حداكثر در مدت 20 روز از تاريخ آمادگي كار كه به تائيد مهندس مشاور رسيده است ، در محل كار حاضر شود و براي تحويل موقت اقدام نمايد . اگر به نظر مهندس مشاور عمليات موضوع پيمان آماده بهره برداري نباشد ، ظرف مدت 7 روز از دريافت تقاضاي پيمانكار ، نواقص و كارهايي را كه بايد پيش از تحويل موقت تكميل شود به اطلاع پيمانكار مي رساند .
هيات تحويل موقت متشكل است از :
نماينده كارفرما
نمانده مهندس مشاور
نماينده پيمانكار
كارفرما تاريخ و محل تشكيل هيات را به اطلاع مهندس مشاور و پيمانكار مي رساند و تا 
تشكيل هيات ، مهندس مشاور ، برنامه زمان هاي آزمايشهايي را كه براي تحويل كار لازم است تهيه و به پيمانكار ابلاغ مي كند تا آن قسمت از وسايل را كه تدارك آنها طبق اسناد و مدارك پيمان به عهده اوست ، براي روز تشكيل هيات در محل كار آماده كند . پيمانكار موظف است كه تسهيلات لازم را براي هيات تحويل ، فراهم نمايد .
آزمايش هاي لازم به تشخيص و با نظر اعضاي هيئت در محل انجام مي شود و نتايج آن در صورت مجلس تحويل موقت درج مي گردد . به جز آزمايشهايي كه طبق اسناد و مدارك پيمان هزينه آنها به عهده پيمانكار است ، هزينه آزمايشها را كارفرما پرداخت مي كند .
هرگاه هيئت تحويل عيب و نقصي در كارها مشاهده نكنند اقدام تنظيم صورت جلسه تحويل موقت 
مي نمايد . صورت جلسه تحويل موقت را به همراه نتيجه آزمايش هاي انجام شده ، براي كارفرما ارسال مي كنند و نسخه اي از آن را نيز تا ابلاغ از سوي كارفرما در اختيار پيمانكار قرار مي دهد كارفرما بعد از تائيد ، تحويل موقت عمليات موضوع پيمان را به پيمانكار ابلاغ مي نمايد .
هرگاه هيئت تحويل عيب و نقصي دركارها مشاهده نمايند ، اقدام به تشكيل صورت جلسه تحويل موقت با تعيين مهلتي براي رفع نقص مي كند و فهرستي از نقايص و معايب كارها و عمليات ناتمام و آزمايش هايي كه نتيجه آن بعداً معلوم مي شود را تنظيم و ضميمه صورت جلسه تحويل موقت مي نمايد و نسخه اي از آنها را به پيمانكار مي دهد . پس از اعلام رفع نقص از جانب پيمانكار ، مهندس مشاور به اتفاق نماينده كارفرما ، دوباره عمليات را بازديد مي كند و اگر بر اساس فهرست نقايص تعيين شده ، هيچ گونه عيب و ايرادي باقي نمانده باشد ، مهندس مشاور ، صورت جلسه تحويل موقت و گواهي رفع نقايص و معايب را به امضا ي نماينده كارفرما ، مهندس مشاور و پيمانكار رسيده است ، همراه نتايج آزمايش هاي خواسته شده براي كارفرما ارسال مي كند تا پس از تائيد كارفرما ، به پيمانكار ابلاغ مي شود . اگر به تشخيص كارفرما حضور نماينده او در بازديد از كار و گواهي رفع نقص ضروري نباشد ، به مهندس مشاور نمايندگي مي دهد تا به جاي نماينده كارفرما اقدام كند .
تاريخ تحويل موقت ، تاريخ تشكيل هيات در محل و تحويل كار به كارفرماست . كه در صورت مجلس تحويل موقت درج مي شود . تاريخ شروع دوره تضمين ، تاريخ تحويل موقت است . به شرط آنكه هيات تحويل ، هيچ گونه نقصي در كار مشاهده نكند يا نقايص در مهلتي كه از طرف هيات تعيين شده است رفع مي شود . اگر زماني كه پيمانكار صرف ، رفع نقايص مي كند ، بيش از مهلت تعيين شده باشد ، تاريخ تحويل موقت ، همان تاريخ تشكيل هيات و تحويل كار به كارفرماست ، ولي تاريخ شروع دوره تضمين ، تاريخ رفع نقص است كه به تائيد مهندس مشاور رسيده باشد .
اگر هيات تحويل موقت ، دير تر از موعد مقرر ( 20 روز از تاريخ اعلام  آمادگي كار از سوي پيمانكار كه به تائيد مهندس مشاور رسيده است )در محل حاضر شود و براي تحويل موقت اقدام نمايد ، تاريخ تحويل موقت ، تاريخ تشكيل هيات در محل و تحويل كار به كارفرماست . در اين حالت ،‌اگر هيات نقصي در كار مشاهده نكند يا نقايصي در مهلتي كه از سوي هيئت تعيين شده است رفع شود ، تاريخ شروع تضمين 20 روز بعد از تاريخ اعلام آمادگي كار از سوي پيمانكار كه به تائيد مهندس مشاور رسيده است مي باشد ، مگر آنكه زماني كه پيمانكار صرف رفع نقص مي كند بيش از مهلت تعيين شده باشد كه در اين صورت ، تاريخ شروع دوره تضمين ، برابر تاريخ رفع نقص كه به تائيد مهندس مشاور رسيده است منهاي مدت تاخير تشكيل هيات در محل ( نسبت به مهلت 20 روز ) مي باشد . كارفرما بايد هزينه هاي حفظ و نگه داري از كار براي مدت تاخير در تحويل موقت (نسبت به مهلت 20 روز ) به پيمانكار پرداخت كند .
ب) در صورتي كه در اسناد و مدارك پيمان ، براي تكميل و تحويل موقت قسمت هاي مستقلي از كار ، زمان هاي مجزايي پيش بيني شده باشد ، يا به نظر كارفرما ، بهره برداري از قسمت هاي مستقلي از كار پيش از تكميل كل كار مورد نياز باشد ، كارفرما با رعايت اين ماده ، قسمت هاي پيش گفته را تحويل موقت گرفته و اقدام هاي پس از تحويل موقت مانند آزاد نمودن تضمين انجام تعهدات ، شروع دوره تضمين ، تحويل قطعي ، استرداد كسور تضمين حسن انجام كار ، را به تناسب آن قسمت از كار كه تحويل موقت گرديده است ، طبق اسناد و مدارك  پيمان ، به صورت مستقل انجام مي دهد .
ج) اگر با توجه به بند ( الف ) ماده 29 ، عمليات موضوع پيمان تا حد 125 درصد مبلغ اوليه پيمان انجام شود ، ولي كار هاي اجرا شده قابل بهره برداري نباشد و پيمانكار براي ادامه كار موافقت نكند ، كارفرما طبق ماده 48 به پيمان خاتمه مي دهد .
د) در صورتي كه عمليات موضوع پيمان طبق اين ماده آماده تحويل موقت شود ، ولي پيمانكار تقاضاي تحويل كار نكند ، مهندس مشاور آماده بودن كار براي تحويل موقت را به كارفرما اعلام مي نمايد تا كارفرما طبق اين ماده براي تشكيل هيات و تحويل كار اقدام كند .اگر بعد از 10 روز از تاريخ ابلاغ كارفرما ، پيمانكار نماينده خود را براي تحويل موقت معرفي نكند ، كارفرما با تامين دليل به وسيله دادگاه محل ، نسبت به تحويل موقت موضوع پيمان ، طبق اين ماده  اقدام مي نمايد . در اين حالت ، پيمانكار حق هيچ گونه اعتراضي را در اين مورد ندارد .
ه) پس از تقاضاي پيمانكار براي تحويل موقت ، در صورتي كه آماده بودن كار براي تحويل موقت مورد تائيد مهندس مشاور باشد ولي تداركات لازم براي راه اندازي و انجام آزمايش هاي مورد نياز مانند آب و برق كه بايد از سوي كارفرما تامين شود فراهم نباشد ، نحوه تحويل موقت و تحويل قطعي و آزاد كردن تضمين هاي پيمانكار با رعايت حقوق طرفين پيمان طبق نظر هياتي متشكل از نماينده سازمان برنامه و بودجه ، نماينده كارفرما و نماينده پيمانكار مي باشد . نظر اين هيات قطعي و لازم الاجرا است .
و ) پيمانكار موظف است كه پس از تحويل موقت ، وسايل ، ماشين آلات و ابزار و مصالح اضافي متعلق به خود در محل هاي تحويلي كارفرما را ظرف مدت مناسبي كه مورد قبول مهندس مشاور باشد ، از محل هاي ياد شده خارج كند . به علاوه پيمانكار ، بايد ظرف مدت معيني كه توسط مهندس مشاور تعيين مي شود ساختمانها و تاسيسات موقتي را كه براي اجراي كار در محل هاي تحويلي كارفرما ساخته است تخريب يا پياده كند و مصالح و مواد زائد آن را از محل كار خارج و كارگاه را به هزينه خود تميز كند . در غير اين صورت كارفرما مي تواند براي خارج نمودن آنها به هر نحوي كه مقتضي بداند عمل نمايد و هزينه هاي آن را به حساب بدهكاري پيمانكار منظور نمايد . در اين صورت پيمانكار حق اعتراضي نسبت به اقدام كارفرما و ادعاي ضرر و زيان به اموال و دارايي هاي خود را ندارد .
با توجه به اين كه مالكيت هاي ساختمان هاي پيش ساخته و مصالح بازيافتي و قطعات پيش ساخته ساختمانها و تاسيسات تجهيز كارگاه كه به وسيله پيمانكار در محل هاي تحويلي كارفرما نصب يا احداث نموده است ، متعلق به پيمانكار است ، هرگاه تمام يا قسمتي از اين ساختمان ها و تاسيسات موقت پيمانكار مورد احتياج كارفرما باشد ، با توجه به اينكه در اين حالت نبايد وجهي بابت برچيدن ساختمانها و تاسيسات ياد شده به پيمانكار پرداخت شود ، قيمت آن با تراضي طرفين تعيين و به كارفرما فروخته و تحويل مي شود .', 'این ماده بیان‌کننده فرآیند تحویل موقت کار پس از اتمام عملیات اجرایی است. بر اساس این حکم، پس از اعلام آمادگی پیمانکار و تأیید آماده بودن کار، کارفرما نسبت به بررسی و تحویل موقت اقدام می‌کند. هدف از این مقرره، انتقال مرحله‌ای مسئولیت بهره‌برداری و آغاز دوره تضمین است.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (40, 4, 40, 'صورت وضعيت قطعي', 'پيمانكار بايد حداكثر تا يك ماه از تاريخ تحويل موقت ، صورت وضعيت قطعي كار هاي انجام شده را بر اساس اسناد و مدارك پيمان ، بدون منظور نمودن مصالح و تجهيزات پاي كار تهيه كند و براي رسيدگي به مهندس مشاور تسليم نمايد . مهندس مشاور صورت وضعيت دريافت شده را رسيدگي نموده و ظرف مدت سه ماه براي تصويب كارفرما ارسال مي نمايد .
كارفرما صورت وضعيت دريافت شده را ظرف مدت 2 ماه از تاريخ وصول رسيدگي مي كند و نظر نهايي خود را ضمن ارسال يك نسخه از آن به پيمانكار ، اعلام مي دارد .
در صورتي كه پيمانكار ، ظرف مهلت تعيين شده ، براي تهيه صورت وضعيت قطعي اقدام نكند ، با تاييد كارفرما ، مهندس مشاور به هزينه پيمانكار ، اقدام به تهيه آن مي كند و بعد از امضاي پيمانكار براي تصويب كارفرما ارسال مي دارد . در صورتي كه پيمانكار از امضاي صورت وضعيت خودداري كند ، مهندس مشاور بدون امضاي پيمانكار ، صورت وضعيت را براي كارفرما مي فرستد .
در حالتي كه پيمانكار ، صورت وضعيت را قبلاً امضا نموده است اگر اعتراضي نسبت به نظر كارفرما داشته باشد يا در حالتي كه صورت وضعيت را قبلاً امضا نكرده است و نسبت به نظر كارفرما اعتراض دارد ، اعتراض خود را حداكثر ظرف يك ماه از تاريخ وصول وضعيت ، با ارائه دليل و مدرك ، يكجا به اطلاع كارفرما مي رساند . كارفرما حداكثر ظرف مدت يك ماه از تاريخ وصول نظر پيمانكار ، به موارد اعتراض رسيدگي مي كند و قبول يا رد آنها را اعلام مي نمايد .
پيمانكار مي تواند براي تعيين تكليف آن قسمت از اعتراض خود كه مورد قبول كارفرما واقع نمي شود ، طبق ماده 53 اقدام نمايد .
در صورتي كه پيمانكار ظرف مدت تعيين شده به صورت وضعيت اعتراض نكند ، صورت وضعيت قطعي از طرف پيمانكار قبول شده تلقي مي شود .
مقادير كارها به ترتيب بالا در صورت وضعيت قطعي منظور مي شود ، به تنهايي قاطع است و ماخذ تسويه حساب قرار مي گيرد ، هرچند كه بين آنها و مقاديري كه در صورت وضعيت هاي موقت منظور گرديده است ، اختلاف باشد .
هرگاه با توجه به صورت وضعيت قطعي تصويب شده و ساير حساب هاي پيمانكار ، پيمانكار بدهكار نباشد ، نصف تضمين حسن انجام كار آزاد مي شود .
تبصره . در مواردي كه طبق مواد 47 يا 48 پس از فسخ يا خاتمه پيمان ، اقدام به تهيه صورت وضعيت قطعي مي شود ، مهلت تهيه صورت وضعيت قطعي ، به ترتيب از تاريخ صورت برداري يا تاريخ تحويل كارهاي انجام شده مي باشد .', 'این ماده بیان‌کننده نحوه تهیه و رسیدگی به صورت وضعیت قطعی پیمانکار است. بر اساس این حکم، کلیه عملیات انجام‌شده پس از تکمیل و بررسی نهایی اندازه‌گیری و محاسبه می‌شود. هدف از این مقرره، تعیین دقیق مطالبات نهایی پیمانکار و مبنای تسویه قرارداد است.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (41, 4, 41, 'تحويل قطعي', 'در پايان دوره تضمين تعيين شده در ماده 5 موافقت نامه ، كارفرما بنا به تقاضاي پيمانكار و تائيد مهندس مشاور ، اعضاي هيات تحويل قطعي و تاريخ تشكيل هيات را ، به همان گونه كه در ماده 39 براي تحويل موقت پيش بيني شده است ، معين و به پيمانكار ابلاغ مي كند . هيات تحويل قطعي ، پس از بازديد كارها ، هرگاه عيب و نقصي كه ناشي از كار پيمانكار باشد مشاهده ننمايد موضوع پيمان را تحويل قطعي مي گيرد . و بي درنگ صورت جلسه آن را تنظيم و براي كارفرما ارسال مي كند و نسخه اي از آن را تا ابلاغ از سوي كارفرما، به پيمانكار مي دهد ، و سپس كارفرما با تصويب تحويل قطعي كار را به پيمانكار ابلاغ مي نمايد .
تبصره 1. هرگاه هيات تحويل قطعي ، عيب و نقصي ناشي از كار پيمانكار مشاهده  كند ، براي رفع آنها طبق ماده 42 رفتار مي شود .
تبصره 2 . اگر پيمانكار در  پايان دوره تضمين تعيين شده در ماده 5 موافقت نامه ، تقاضاي تحويل قطعي كار را ننمايد ، مكلف به رفع نواقص ناشي از كار خود كه تا تاريخ تقاضاي تحويل قطعي بروز كرده است مي باشد و تاريخ تقاضاي پيمانكار ملاك اقدامات مربوط به تحويل قطعي است .
تبصره 3. اگر كارفرما با وجود تقاضاي پيمانكار ، اقدام به اعزام هيات تحويل نكند و اين تاخير بيش از دو ماه به طول انجامد و پس از درخواست مجدد پيمانكار و انقضاي يك ماه از تاريخ تقاضاي مجدد كارفرما در اين زمينه اقدامي نكند ، عمليات موضوع پيمان تحويل قطعي شده تلقي مي گردد و بايد اقدامات پس از تحويل قطعي در مورد آن انجام شود .', 'این ماده بیان‌کننده شرایط و تشریفات تحویل قطعی پروژه پس از پایان دوره تضمین است. بر اساس این حکم، پس از رفع نواقص احتمالی و تأیید کارفرما، تحویل قطعی انجام می‌شود. هدف از این مقرره، اطمینان از صحت عملکرد کار و پایان مسئولیت‌های اجرایی پیمانکار است.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (42, 4, 42, 'مسئوليت هاي دوره تضمين', 'اگر در دوره تضمين ، معايب و نواقصي در كار ببيند كه ناشي از كار پيمانكار باشد ، پيمانكار مكلف است كه آن معايب و نواقص را به هزينه خود رفع كند . براي اين منظور ، كارفرما مراتب را با ذكر معايب و نواقص و محل آنها به پيمانكار ابلاغ مي كند و پيمانكار بايد حداكثر 15 روز پس از ابلاغ كارفرما ، شروع به رفع معايب و نواقص مي كند و آنها را طي مدتي كه مرد قبول كارفرماست ، رفع نمايد .
هرگاه پيمانكار در انجام اين تعهد قصور ورزد يا مسامحه كند ، كارفرما حق دارد آن معايب را خودش يا به ترتيبي كه مقتضي بداند رفع نمايد و هزينه آن را به اضافه 15 درصد ، از محل تضمين پيمانكار يا هر نوع مطالبات و سپرده اي كه پيمانكار نزد او دارد ، برداشت نمايد .
هزينه هاي حفاظت ، نگه داري و بهره برداري كارهاي تحويل موقت شده در دوره تضمين به عهده كارفرماست .', 'حالت های ی که منجر به حوادث قهری می شوند:
1- خارج از اراده طرفین باشد
2- قابل مقاومت نباشد.
3- در حین تنظیم قرارداد پیش بینی آن ممکن نباشد.
4- مانع از اجرای تعهد باشد.
5- در حوزه قلمرو کاری باشد.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (43, 5, 43, 'بروز حوادث قهري', 'جنگ ، اعم از اعلام شده يا نشده ،انقلاب ها و اعتصاب هاي عمومي ، شيوع بيماري هاي واگير دار ، زلزله ، سيل ، و طغيان هاي غير عادي‌ ،‌آتش سوزي هاي دامنه دار و مهار نشدني ، طوفان ، و حوادث مشابه خارج از كنترل دو طرف پيمان كه در منطقه اجراي كار وقوع يابد و ادامه كار را براي پيمانكار ناممكن سازد جزء حوادث قهري به شمار مي آيد و در صورت بروز آنها ، به ترتيب زير عمل مي شود . در بروز حوادث قهري، هيچ يك از دو طرف مسئول خسارت هاي وارده به طرف ديگر در اثر اين حوادث نيست .
الف) پيمانكار موظف است ، كه حداكثر كوشش خود را براي حفاظت از كارهاي اجرا شده كه در وضعيت قهري رها كردن آنها منجر به زيان جدي مي شود و انتقال مصالح و تجهيزات پاي كار به محل هاي مطمئن و ايمن ، به كار برد . كارفرما نيز بايد تمام امكانات موجود خود را در محل ، در حد امكان ، براي تسريع در اين امر ، در اختيار پيمانكار قرار دهد .
ب) در مورد خسارت هاي وارد شده به كار هاي موضوع پيمان ، تاسيسات و ساختمان هاي موقت ، ماشين آلات و ابزار و وسائل پيمانكار به شرح زير عمل مي شود .
1. هرگاه خسارت هاي وارد شده به كارهاي موضوع پيمان ، مشمول بيمه موضوع بند (ج) ماده 21 باشد براي جبران آن ، طبق همان ماده اقدام مي شود .
2. اگر خسارت هاي وارد شده به كارهاي موضوع پيمان ، مشمول بيمه موضوع بند (ج) ماده 21 نيست يا ميزان آنها براي جبران خسارتها كافي نباشد جبران خسارت به عهده كارفرماست .
3. جبران خسارت هاي وارد شده به ساختمانها و تاسيسات موقت ، ماشين آلات و ابزار و وسايل پيمانكار ، با توجه به بند (د) ماده 21 ، به عهده پيمانكار است .
منظور از جبران خسارت هاي ياد شده ، در بند هاي ( ب-1)و (ب-2) ، اعاده كارها به صورت پيش از وقوع حادثه است . پس از رفع وضعيت قهري ، اگر كارفرما اعاده كارها را به حالت پيش از وقوع حادثه لازم و ميسر بداند ، پيمانكار مكلف است  كه اجراي كارها را بي درنگ آغاز نمايد . در اين صورت ، تمديد مدت مناسبي براي اعاده كارها به وضع اول ، از سوي پيمانكار پيشنهاد مي شود كه پس از رسيدگي و تائيد مهندس مشاور و تصويب كارفرما ، به پيمانكار ابلاغ مي گردد .
ج) اگر كارفرما ادامه كارها به وضع اوليه را ضروري تشخيص ندهد ، يا اگر وضعيت قهري بيش از شش ماه ادامه يابد ، بدون رعايت بند (د) ماده 48 طبق ماده 48 ، به پيمان خاتمه مي دهد .
كارفرما هزينه توقف  كار پيمانكار را براي مدت مازاد بر يك ماه ،طبق بند هاي (ب) و (ج) ماده 49 پرداخت مي كند .', 'این ماده بیان‌کننده آثار حوادث قهری و خارج از اختیار طرفین بر اجرای پیمان است. بر اساس این حکم، در صورت وقوع حوادث غیرقابل پیش‌بینی مانند بلایای طبیعی، مسئولیت‌ها و نحوه ادامه یا خاتمه پیمان طبق مقررات تعیین می‌شود. هدف از این مقرره، تعیین تکلیف شرایط اضطراری و حمایت از حقوق طرفین است.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (44, 5, 44, 'ممنوعيت قانوني', 'پيمانكار اعلام مي كند كه در موقع عقد پيمان ، مشمول قانون منع مداخله ، مصوب بيست و دوم دي ماه هزار و سيصد و هفت نيست و در صورتي كه خلاف آن براي كارفرما محرز شود ، پيمان فسخ و طبق ماده 47 رفتار مي شود .
هرگاه ضمن انجام كار تحويل موقت ، پيمانكار ، به علل زير مشمول قانون پيشگفته مي شود :
الف ) تغييراتي كه در صاحبان سهام ، مدير يا بازرسان شركت پيمانكار پيش آيد .
ب) تغييراتي كه در دستگاه هاي دولت يا كارفرما پيش آيد .
در حالت الف پيمان فسخ و طبق ماده 47 رفتار مي شود . در حالت ب به محض وقوع منع قانوني ، پيمانكار مكلف است كه مراتب را به كارفرما اعلام كند و در صورتي كه منع قانوني رفع نشود كارفرما به پيمان خاتمه مي دهد و طبق ماده 48 با پيمانكار عمل مي شود . اگر پيمانكار مراتب را به موقع به كارفرما اعلام نكند پيمان فسخ و طبق ماده 47 رفتار مي شود .', 'این ماده بیان‌کننده آثار ممنوعیت‌های قانونی مؤثر بر اجرای پیمان است. بر اساس این حکم، چنانچه اجرای قرارداد به دلیل قوانین یا مقررات ممنوع شود، وضعیت پیمان مطابق مقررات تعیین خواهد شد. هدف از این مقرره، پیش‌بینی آثار حقوقی موانع قانونی اجرای قرارداد است.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (45, 5, 45, 'حقوق انحصاري ثبت شده', 'الف) پيمانكار ، كارفرما را در مقابل تمام دعاوي ، خسارتها و مطالبات مربوط به نقض احتمالي حقوق ثبت شده ، تاليفات ، علايم يا نام هاي تجاري و ديگر حقوق حمايت شده كه در اجراي موضوع پيمان ايجاد شود ، مصون مي دارد .
ب) كارفرما تائيد مي كند كه مفاد اسناد و مدارك پيمان به گونه اي نيست كه موجب نقض حقوق حمايت شده شود . در صورتي كه براي پيمانكار معلوم شود كه رعايت اسناد و مدارك پيمان ناگزير در مواردي موجب نقض حقوق حمايت شده مي گردد ، بايد پيش از هر نوع اقدام در مورد آنها، مراتب را به مهندس مشاور اعلام نمايد تا كارفرما نسبت به ايجاد تغييرات لازم ، به گونه اي كه نقص حقوق حمايت شده برطرف شود ، اقدام نمايد  و نتيجه را به پيمانكار ابلاغ نمايد .', 'این ماده بیان‌کننده وضعیت حقوق انحصاری ثبت‌شده در اجرای موضوع پیمان است. بر اساس این حکم، رعایت حقوق مالکیت فکری و انحصاری اشخاص در استفاده از طرح‌ها، تجهیزات یا فناوری‌ها الزامی است. هدف از این مقرره، جلوگیری از نقض حقوق قانونی اشخاص ثالث است.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (46, 5, 46, 'موارد فسخ پيمان', 'الف ) كارفرما مي تواند در صورت تحقق هر يك از موارد زير پيمان را طبق ماده 47 فسخ نمايد :
تاخير در تحويل گرفتن كارگاه براي شروع عمليات موضوع پيمان ، بيش از نصف مدت تعيين شده در بند (ب) ماده 28.
تاخير در ارائه برنامه زماني تفصيلي به مدت بيش از نصف مهلت تعيين شده براي تسليم آن .
تاخير در تجهيز كارگاه براي شروع عمليات موضوع پيمان ، بيش از نصف مدت تعيين شده در بند (ج) ماده 4 موافقت نامه . فسخ پيمان در اين حالت ، در صورتي مجاز است كه كارفرما قسمتي از پيش پرداخت را كه بايد بعد از تحويل كارگاه پرداخت نمايد ، پرداخت گرده باشد .
تاخير در شروع عمليات موضوع پيمان، بيش از يك دهم مدت اوليه پيمان يا دو ماه ، هر كدام كه كمتر است .
تاخير در اتمام هر يك از كار هاي پيش بيني شده در برنامه تفصيلي ، بيش از نصف مدت تعيين شده براي آن كار با توجه به ماده 30 .
تاخير در اتمام به مدت بيش از يك چهارم مدت پيمان با توجه به  ماده 30.
عدم شروع كار پس از رفع وضعيت قهري موضوع ماده 43 و ابلاغ شروع كار از سوي كارفرما .
بدون سرپرست گذاشتن كارگاه يا تعطيل كردن كار ، بدون اجازه كارفرما ، بيش از 15 روز
عدم انجام دستور مهندس مشاور براي اصلاح كارهاي انجام شده معيوب ، طبق بند (د) ماده 32.
انحلال شركت پيمانكار
ورشكستگي پيمانكار يا توقيف ماشين آلات و اموال پيمانكار از سوي محاكم قضايي ، به گونه اي كه موجب توقف يا كندي پيشرفت كار شود .
تاخير بيش از يك ماه در پرداخت دستمزد كارگران ، طبق بند (و ) ماده 17.
هرگاه ثابت شود كه پيمانكار براي تحصيل پيمان يا اجراي آن به عوامل كارفرما حق العمل ، پاداش يا هدايايي داده است ، يا آنها را واسطه هاي آنها را در منافع خود سهيم كرده است .
ب)در صورت احراز موارد زير ، كارفرما پيمان را فسخ مي كند :
1- واگذاري پيمان به شخص ثالث
2- پيمانكار مشمول ممنوعيت قانوني ماده 44 گردد ، به استثناي حالت پيش بيني شده در بند (ب) آن ، براي شمول ماده 48.', 'این ماده بیان‌کننده موارد و شرایطی است که کارفرما می‌تواند نسبت به فسخ پیمان اقدام کند. بر اساس این حکم، در صورت وقوع تخلفات اساسی یا قصور پیمانکار، کارفرما مطابق تشریفات مقرر حق فسخ پیمان را خواهد داشت. هدف از این مقرره، حمایت از حقوق کارفرما و تضمین اجرای تعهدات پیمانکار است.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (47, 5, 47, 'اقدامات فسخ پيمان', 'الف ) در صورتي كه به علت بروز يك يا چند مورد  از حالت هاي درج شده در ماده 46 ، كارفرما پيمان را مشمول فسخ تشخيص دهد ، نظر خود را با ذكر مواردي كه به استناد آنه پيمانكار را مشمول فسخ مي داند ، به پيمانكار ابلاغ مي كند .
پيمانكار مكلف است كه در مدت 10 روز از تاريخ ابلاغ كارفرما ، در صورتي كه دلايلي حاكي از عدم انطباق نظر كارفرما با موارد اعلام شده داشته باشد ، مراتب را به اطلاع كارفرما برساند . اگر ظرف مدت تعيين شده ، پاسخي از سوي پيمانكار نرسد يا كارفرما دلايل اقامه شده را مردود بداند ، كارفرما فسخ پيمان را به پيمانكار ابلاغ مي كند و بدون احتياج به انجام دادن تشريفات قضايي ، به ترتيب مفاد اين ماده ، عمل مي نمايد .
در صورتي كه تصميم كارفرما براي فسخ پيمان به استناد موارد درج شده در بند الف ماده 46 باشد ، موضوع فسخ پيمان بايد بدواً به وسيله هياتي متشكل از سه نفر به انتخاب وزير يا بالاترين مقام سازمان كارفرما ( در مورد سازمانهايي كه تابع هيچ يك از وزارت خانه ها نيستند ) بررسي و تائيد شود و مورد موافقت وزير يا بالاترين مقام سازمان كارفرما قرار گيرد و سپس به پيمانكاران ابلاغ شود .
ب) كارفرما تضمين انجام تعهدات و تضمين حسن انجام كار كسر شده را ضبط و به حساب خزانه واريز مي كند و بي درنگ كارگاه و تاسيسات و ساختمان هاي وقت ، مصالح و تجهيزات ، ماشين آلات و ابزار و تمام تداركات موجود در آن در اختيار مي گيرد و براي حفاظت آن اقدام لازم را معمول مي دارد . سپس بي درنگ از پيمانكار دعوت مي كند كه ظرف يك هفته نماينده اي براي صورت برداري و صورت مجلس كار هاي انجام شده و تمام مصالح و تجهيزات ، ماشين آلات و ابزار و تداركات ديگري كه در كارگاه موجود است معرفي نمايد . هرگاه پيمانكار از معرفي نماينده ظرف مدت تعيين شده خودداري نمايد يا نماينده معرفي شده از جانب او در موعد مقرر براي صورت برداري حاضر نشود ، كارفرما به منظور تامين دليل با حضور نماينده دادگاه محل ، براي صورت برداري اقدام مي نمايد و پيمانكار حق هيچ گونه اعتراضي در اين مورد ندارد . پس از صورت برداري ، پيمانكار بي درنگ ، طبق ماده 40 اقدام به تهيه صورت وضعيت قطعي از كارهاي انجام شده مي كند .
ج)كارفرما تاسيسات و ساختمان هاي موقت را كه در كارگاه احداث شده و براي ادامه كار مورد نياز است ، در اختيار مي گيرد و بهاي آن را برابر ارزش مصالح و تجهيزات بازيافتي كه با توافق دو طرف تعيين مي شود با توجه به اينكه در اين موارد نبايد وجهي بابت برچيدن كارگاه به پيمانكار پرداخت شود ، به حساب طلب پيمانكار منظور مي كند . اگر تاسيسات و ساختمان هاي پيشگفته در خارج از محل هاي تحويلي كارفرما ايجاد شده باشد ، كارفرما بهاي اجاره آنها را با توافق دو طرف تعيين مي شود ، براي مدتي كه به منظور تكميل كار در اختيار خواهد داشت به پيمانكار پرداخت مي كند .
د) كارفرما مي تواند ماشين آلات و ابزار و وسايل متعلق به پيمانكار را كه در كارگاه كه موجود است و به تشخيص خود براي اتمام كار مورد نياز بداند ، براي مدت مناسبي كه براي جايگزين كردن آنها با ماشين آلات ديگر لازم است در اختيار بگيرد و هزينه اجاره آنها را كه با توافق دو طرف  تعيين مي شود ، به حساب طلب پيمانكار منظور نمايد . كارفرما نمي تواند بدون موافقت پيمانكار ماشين آلات او را بيش از مدت هاي تعيين شده در زير اجاره خود بگيرد .
1- در مورد ماشين آلات ثابت مانند دستگاه مركزي بتن ، كارخانه آسفالت و ماشين آلات خاصي كه نام آنها در شرايط خصوصي پيمان پيش بيني شده است ، برابر مدتي كه از رابطه زير به دست مي آيد .
2- در مورد ساير ماشين آلات ، برابر ده ماه .
اگر پيمانكار به كارفرما بدهكار باشد ، كارفرما به ميزان طلب خود ، اقلامي از ماشين آلات و ابزار و وسائل پيمانكار را كه توسط كارشناس يا كارشناسان منتخب طرفين ارزيابي مي شود در اختيار مي گيرد و با رعايت قوانين جاري كشور ، به تملك قطعي خود در مي آورد .
ه) كارفرما از مصالح و تجهيزات پاي كار آنچه طبق مشخصات بوده و براي اجراي پيمان تهيه شده است قبول مي كند و بهاي آن را بر اساس نرخ متعارف روز در تاريخ خريد كه مورد توافق دو طرف باشد به حساب طلب پيمانكار منظور مي نمايد .
و) پيمانكار با دريافت ابلاغ فسخ پيمان ، بي درنگ فهرست مصالح سفارش شده براي اجراي كار را همراه با شرايط خريد آنها براي كارفرما ارسال  مي نمايد . كارفرما تا 10 روز از دريافت فهرست پيشگفته اقلامي از مصالح و تجهيزات سفارش شده را كه مورد نياز تشخيص مي دهد به پيمانكار اعلام مي نمايد تا پيمانكار قرارداد خريد آنها را به كارفرما منتقل نمايد . مبالغي كه بابت خريد اين مصالح و تجهيزات از سوي پيمانكار تاديه شده است ، در مقابل تسليم اسناد و مدارك آن به حساب طلب پيمانكار منظور مي گردد و تاديه بقيه بهاي خريد و هر نوع تعهد مربوط به آنها به عهده كارفرما خواهد بود .
ز)هرگاه پيمانكار ظرف دو هفته از تاريخ ابلاغ كارفرما ، به منظور توافق در اجراي بند هاي (ج)و (د) و (ه) حاضر نشود يا توافق بين طرفين حاصل نگردد ، كارفرما يك يا چند كارشناس رسمي دادگستري انتخاب مي نمايد . نظر اين كارشناس يا كارشناسان براي طرفين قطعي است و حق الزحمه آنان را كارفرما مي پردازد و به حساب بدهي پيمانكار منظور مي كند .
ح) پيمانكار مكلف است كه مازاد مصالح و تجهيزات و ديگر تداركات خود را كه در محل هاي تحويلي كارفرما باقي مانده است ، حداكثر ظرف 3 ماه از تاريخ ابلاغ كارفرما ، از محل هاي ياد شده خارج كند . در غير اينصورت كارفرما مي تواند براي خارج كردن آنها به هر نحو كه مقتضي بداند عمل نمايد و هزينه هاي آن را به حساب بدهكاري هاي پيمانكار منظور دارد .
ط) از تاريخ ابلاغ فسخ پيمان تا تاريخي كه صورت برداري ها و ارزيابي طبق اين ماده پايان مي يابد ، نصف هزينه هاي مربوط به نگه داري و حفاظت كارگاه به عهده كارفرما و نصف ديگر به عهده پيمانكار است . اين مدت نبايد از سه ماه بيشتر شود ، در غير اين صورت هزينه هاي مربوط به نگه داري و حفاظت كارگاه براي ايام بيش از سه ماه به عهده كارفرماست .', 'کارفرما از دو گونه حق فسخ برخوردار است:

فسخ پیمان به استناد ماده 46 شرایط عمومی پیمان
انحلال پیمان به استناد ماده 48 شرایط عمومی پیمان                                                      در حالت اول اثر فسخ برای پیمانکار زیان بار است اما در حالت دوم اثر آن چنانی متوجه پیمانکار نیست.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (48, 5, 48, 'خاتمه پيمان', 'هرگاه پيش از اتمام كارهاي موضوع پيمان ، كارفرما بدون آنكه تقصيري متوجه پيمانكار باشد ،‌بنا به مصلحت خود يا علل ديگر ، تصميم به خاتمه دادن پيمان بگيرد ، خاتمه پيمان را با تعيين تاريخ آماده كردن كارگاه براي تحويل ، كه نبايد بيشتر از 15 رز باشد به پيمانكار ابلاغ مي كند . كارفرما كارهايي را كه ناتمام ماندن آنها موجب بروز خطر يا زيان مسلم است در اين ابلاغ تعيين مي كند و مهلت بيشتري به پيمانكار مي دهد تا پيمانكار بتواند در آن مهلت ، اين گونه كارها را تكميل كند و كارگاه را آماده تحويل نمايد .
اقدامات بعد از خاتمه دادن پيمان به شرح زير است :
الف ) كارفرما آن قسمت از كارها را كه ناتمام است ، طبق مقررات درج شده در ماده 41 تحويل قطعي و آن قسمت را كه پايان يافته است طبق مقررات تعيين شده در ماده 39 تحويل موقت مي گيرد . اگر معايبي در مورد كارهاي ناتمام مشاهده شود ، پيمانكار مكلف است ، به هزينه خود ، در مدت مناسبي كه با توافق كارفرما تعيين مي شود ف رفع عيب نمايد و سپس تحويل قطعي دهد . در صورتي كه پيمانكار در مهلت مقرر رفع نقص نكند ، كارفرما طبق بد (د) ماده 32 اقدام به رفع نقص مي نمايد . تا حدي كه مورد لزوم و درخواست كارفرماست ،پيمانكار بايد نقشه ها ، كاتولوگ ها ، قرارداد هاي با پيمانكاران جزء و ساير مدارك اجراي كار را تحويل كارفرما دهد .
ب) صورت وضعيت كارهاي انجام شده ، طبق ماده 40 تهيه مي شود .
ج) در مورد مصالح و تجهيزات موجود و سفارش شده ، به شرح زير اقدام مي شود :
1- مصالح و تجهيزات موجود در كارگاه كه طبق مشخصات فني بوده و براي اجراي موضوع پيمان تهيه شده است ، اندازه گيري بهاي آنرا بر اساس نرخ متعارف روز در تاريخ خريد ، كه مورد توافق دو طرف باشد ، در صورت وضعيت قطعي منظور مي شود .
2- پيمانكار با دريافت ابلاغ خاتمه پيمان ، بي درنگ فهرست مصالح و تجهيزات سفارش شده براي اجراي كار را همراه با شرايط خريد آن براي كارفرما ارسال مي نمايد . كارفرما تا 10 روز از دريافت فهرست پيشگفته ، اقلامي از مصالح و تجهيزات سفارش شده را كه مورد نياز تشخيص مي دهد به پيمانكار اعلام مي كند تا پيمانكار قرارداد خريد آنها را به كارفرما منتقل  نمايد . مبالغي كه بابت خريد اين مصالح و تجهيزات از سوي پيمانكار تاديه شده است ، در مقابل تسليم اسناد و مدارك آن به حساب طلب پيمانكار منظور مي گردد و تاديه بقيه ي بهاي خريد و هر نوع تعهد مربوط به آنها به عهده كارفرما خواهد بود .
3-پيمانكار بايد بي درنگ پس از دريافت ابلاغ خاتمه پيمان ، تمام قرارداد هاي خود را با پيمانكاران جزء و اشخاص ثالث را خاتمه دهد . خاتمه قرارداد هاي خريد مصالح و تجهيزاتي كه مورد نياز كارفرما نيست پس از اعلام نظر كارفرما طبق بند 2 ، انجام شود .
د) در صورت يكه پيمانكار به منظور اجراي موضوع پيمان ، در مقابل اشخاص ثالث تعهداتي كرده است و در اثر خاتمه دادن به پيمان ملزم به پرداخت هزينه و خسارتهايي به آن اشخاص گردد ، اين هزينه ها و خسارتها ، پس از رسيدگي و تائيد كارفرما به حساب بستانكاري پيمانكار منظور مي گردد .
ه)كارفرما تاسيسات و ساختمان هاي موقتي را كه در كارگاه احداث شده است ، در اختيار مي گيرد.
بهاي اين تاسيسات و ساختمانها با در نظر گرفتن پرداختهايي كه قبلاً به پيمانكار شده است ، با توافق دو طرف تعيين مي شود و به حساب طلب پيمانكار منظور مي گردد و بابت آن وجهي به عنوان برچيدن كارگاه پرداخت نمي شود . اگر تاسيسات و ساختمان هاي پيشگفته در خارج از محل هاي تحويلي كارفرما ايجاد شده باشد ، كارفرما بهاي اجاره آنها را با توافق دو طرف تعيين مي شود ، براي مدتي كه به منظور تكميل كار در اختيار داشت به پيمانكار پرداخت مي كند .
و)پيمانكار مكلف است كه مازاد مصالح و تجهيزات و ديگر تداركات خود را كه در محل هاي تحويلي كارفرما باقي مانده است ، حداكثر ظرف مدت 3 ماه از تاريخ ابلاغ كارفرما ، از محل هاي ياد شده خارج كند . در غير اين صورت ، كارفرما مي تواند براي خارج كردن آنها به نحوي كه مقتضي بداند عمل نمايد و هزينه هاي آن را به حساب بدهي پيمانكار منظور كند در اين صورت پيمانكار نمي تواند نسبت به ضرر و زيان وارد شده به اموال و دارايي هاي خود دعوايي مطرح نمايد .
ز) در مورد تضمين هاي پيمانكار ، به ترتيب زير عمل مي شود :
1- تضمين انجام تعهدات پيمان ، طبق روش تعيين شده در تبصره 1 ماده 34 آزاد مي شود ، با اين تفاوت كه آخرين صورت وضعيت موقت موضوع تبصره پيشگفته  حداكثر تا يك ماه پس از تحويل كار ، اعم از قسمت تحويل موقت شده و تحويل قطعي شده ، با احتساب مصالح پاي كار تهيه مي شود .
2- تضمين حسن انجام كار قسمت تحويل موقت شده و قسمت تحويل قطعي شده ، هر يك جداگانه طبق ماده 35 آزاد مي شود .', 'تعهدات کارفرما در دوره تعلیق:

پرداخت هزینه های بالاسری در دوران تعلیق
پرداخت هزینه اجاره ماشین آلات                                                                             تعهدات پیمانکار در دوره تعلیق:

حفاظت از کارگاه به طور شایسته
آماده کردن کارگاه پس از رفع تعلیق                                                                               سه روش پرداخت هزینه تعلیق:

 1- در صورتی که در اسناد و مدارک پیمان میزانی یا روشی برای پرداخت هزینه دوره تعلیق پیش بینی شده باشد.
2- در صورتی که در اسناد و مدارک پیمان تعیین هزینه دوره تعلیق به زمان ابلاغ تعلیق موکول شده باشد.
3- در صورتی که هیچ کدام از دو مورد فوق در اسناد و مدارک پیمان پیش بینی نشده باشد، کارفرما ماهیانه 10 درصد متوسط کارکرد فرضی ماهانه را به پیمانکار پرداخت می نماید.                         تعلیق پیمان از طرف پیمانکار:

 1- در صورت پرداخت نشدن نخستین قسط پیش پرداخت
2- در اثر تعلل یا تاخیر در پرداخت صورت وضعیت های موقت و نیز اقساط بعدی پیش پرداخت.          (این وضعیت بدون ذکر مدت در پیمان، می تواند تا زمان پرداخت تعهدات مالی کارفرما ادامه داشته باشد. در این حالت، چون تأخیرات مجاز پیمانکار ناشی از قصور یا تقصیر وی نمی باشد، پرداخت هزینه های بالاسری پیمانکار بر کارفرما نیز تحمیل می گردد)');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (49, 5, 49, 'تعليق', 'الف )كارفرما مي تواند در مدت پيمان ، اجراي كار را براي يك بار و حداكثر سه ماه معلق كند ، در اين صورت بايد مراتب را با تعيين تاريخ شروع تعليق به پيمانكار اطلاع دهد . در مدت تعليق ، پيمانكار مكلف است كه تمام كارهاي انجام شده ، مصالح و تجهيزات پاي كار ، تاسيسات و ساختمان هاي موقت را بر اساس پيمان به طور شايسته ، حفاظت و حراست كند .
ب)كارفرما هزينه هاي بالاسري پيمانكار را در دوران تعليق به ميزان تعيين شده در اسناد و مدارك پيمان ، تعيين هزينه هاي ياد شده ، به توافق طرفين در زمان ابلاغ تعليق موكول شده باشد ، كارفرما در مورد ميزان آن با پيمانكار توافق مي نمايد . در صورتي كه در اسناد و مدارك پيمان ، هيچ نوع پيش بيني براي پرداخت هزينه هاي بالاسري پيمانكار در دوره تعليق نشده باشد ، كارفرما ماهانه مبلغي معادل 10 درصد متوسط كاركرد فرضي ماهانه را به پيمانكار مي پردازد . اگر به دستور كارفرما ، قسمتي از كار متوقف شود ، بابت هزينه هاي پيشگفته در مدت تعليق ، ماهانه مبلغي معادل 10 در صد متوسط كاركرد فرضي ماهانه ، به تناسب مبلغ كار متوقف شده ، به پيمانكار پرداخت مي شود . براي تعيين هزينه تعليق ، كسر ماه به تناسب محاسبه مي شود .
تبصره : در صورتيكه پيش از آغاز عمليات موضوع پيمان ، تعليق پيمان از سوي كارفرما ابلاغ شود ، 80 درصد هزينه تعليق محاسبه شده طبق اين بند ، به پيمانكار پرداخت مي شود .
ج) كارفرما و پيمانكار در مورد ماشين آلاتي كه پيمانكار مايل است در مدت تعليق از كارگاه خارج نمايد ، بدون پرداخت هيچ نوع هزينه اي ، توافق مي كنند . اجاره مربوط به دوران توقف آن تعداد از ماشين آلات كه در كارگاه باقي مي ماند ، بر اساس توافق طرفين به پيمانكار پرداخت مي شود .
د) در صورتي كه تعليق بيش از سه ماه ضروري باشد ، كارفرما مي تواند با موافقت پيمانكار ، مدت تعليق را براي يك بار و حداكثر 3 ماه ، با شرايط پيش گفته افزايش دهد . در صورت عدم موافقت پيمانكار با تعليق بيش از 3 ماه پيمان خاتمه يافته و طبق ماده 48 عمل مي شود .
ه) هرگاه عوامل موجب تعليق كار برطرف شود ، كارفرما با تعيين مهلتي براي پيمانكار به منظور آماده نمودن كارگاه ، تاريخ شروع مجدد كار را به پيمانكار ابلاغ مي كند .', 'این ماده بیان‌کننده شرایط تعلیق موقت عملیات اجرایی پیمان توسط کارفرما است. بر اساس این حکم، کارفرما می‌تواند در موارد ضروری اجرای کار را متوقف کند و در این مدت تعهدات مربوط به حفاظت کارگاه و پرداخت هزینه‌های مقرر تعیین می‌شود. هدف از این مقرره، تنظیم آثار حقوقی توقف موقت پروژه و حفظ حقوق طرفین است.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (50, 5, 50, 'هزينه تسريع كار ، خسارت تاخير كار', 'الف ) اگر در مقابل پيش از موعد اتمام كار ، در اسناد و مدارك پيمان ، پرداخت هزينه تسريع كار به پيمانكار ، پيش بيني شده باشد و پيمانكار پيش از سپري شدن مدت پيمان ، عمليات موضوع پيمان را تكميل كند و آماده تحويل نمايد ، پيمانكار محق به دريافت هزينه تسريع  طبق شرايط پيش بيني  شده مي باشد .
ب) در پايان كار، در صورتي كه مدت انجام كار ، بيش از مدت اوليه پيمان به علاوه مدت هاي تمديد شده پيمان باشد ، مهندس مشاور با رعايت ماده 30 و رسيدگي به دلايل پيمانكار ، مدت تاخير غير مجاز را تعيين مي كند ، تا پس از تصويب كارفرما ، به شرح زير ، ملاك محاسبه خسارت تاخير قرار گيرد .
1- هرگاه جمع مدت تاخير غير مجاز از يك دهم مدت پيمان بيشتر نشود ، براي هر روز تاخير ، يك دو هزارم مبلغ باقيمانده كار كه در اجراي آن تاخير شده است .
2- هرگاه جمع مدت تاخير غير مجاز از يك دهم مدت پيمان بيشتر شود، تا يك دهم مدت پيمان طبق بند 1 و براي مازاد بر آن تا يك چهارم مدت پيمان ،براي هر روز تاخير يك هزارم مبلغ باقيمانده كار كه در اجراي آن تاخير شده است .
3- هرگاه جمع مدت تاخير غير مجاز از يك چهارم مدت پيمان بيشتر شود ولي پيمان ادامه يابد ، مجموع خسارت هاي تاخير قابل دريافت از پيمانكار نمي تواند از جمع خسارت محاسبه شده بر پايه بند  (2) بيشتر شود و مدت اضافه بر يك چهارم مدت پيمان ، براي ادامه و انجام كار بدون دريافت خسارت منظور مي شود .
4- مبلغ باقي مانده كار كه در اجراي آن تاخير شده است ، عبارت است از مبلغ پيمان ، منهاي مبلغ صورت وضعيت مربوط به كار هاي انجام يافته تا آخرين روز مدت پيمان .
5- در صورتيكه پيمان ، طبق ماده 46 فسخ شود ، يا طبق ماده 48 ، به پيمان خاتمه داده شود ، تاخير كار نسبت به برنامه تفصيلي با رعايت ماده 30 بررسي شده ، ميزان مجاز و غير مجاز آن تعيين 
مي شود بابت تاخير غير مجاز پيمانكار ، طبق مفاد اين بند ، پرداخت خسارت تاخير به پيمانكار تعلق
 مي گيرد . در اين حالت ، مبلغ باقي مانده كار كه در اجراي آن تاخير شده ، عبارت است از مبلغ كارهايي كه طبق برنامه زمان تفصيلي و با در نظر گرفتن تاخير مجاز پيمانكار بايد تا تاريخ فسخ يا خاتمه پيمان انجام مي شد منهاي مبلغ كار انجام شده .
6- در مواردي كه اخذ خسارت تاخير بيش از ارقام درج شده در اين ماده ضروري مي باشد و در اسناد و مدارك پيمان ، ميزان آن پيش بيني شده باشد ، خسارت تاخير را بر اساس آن محاسبه مي كنند .', 'این ماده بیان‌کننده هزینه‌های ناشی از تسریع در اجرای کار یا خسارت‌های مربوط به تأخیر است. بر اساس این حکم، پرداخت هزینه تسریع یا مطالبه خسارت تأخیر باید مطابق شرایط پیمان و پس از احراز شرایط قانونی انجام شود. هدف از این مقرره، ایجاد تعادل میان ضرورت سرعت اجرا و مسئولیت ناشی از تأخیر است.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (51, 5, 51, 'صورت حساب نهايي', 'صورت حساب نهايي پيمان كه ظرف مدت 3 ماه از تاريخ تصويب صورت وضعيت قطعي توسط كارفرما تهيه مي شود ، عبارت است از مبلغ صورت وضعيت قطعي كه طبق ماده 40 تهيه و تصويب ميشود و مبلغي كه بر اساس اسناد و مدارك پيمان به مبلغ بالا اضافه يا از آن كسر مي گردد ، مانند وجوه ناشي از تعديل آحاد بها ، بهاي مصالح ، تجهيزات ، ماشين آلات تحويلي كارفرما به پيمانكار ، مبلغ جبران خسارت يا جريمه هاي رسيدگي و قطعي شده .
صورت حساب نهايي تهيه شده توسط كارفرما در صورتي كه مورد قبول پيمانكار باشد ، توسط كارفرما و پيمانكار امضا مي شود . اگر پيمانكار به صورت حساب نهايي تهيه شده توسط  كارفرما معترض باشد و آن را امضا نكند ، بايد ظرف يك ماه ، نظر خود را با مدارك كافي به كارفرما بنويسد و گر نه صورت حساب نهايي از طرف پيمانكار پذيرفته شده تلقي ميشود .
صورت حساب نهايي تائيد شده به شرح بالا كه ملاك تسويه حساب پيمانكار طبق ماده 52 قرار مي گيرد ، براي دو طرف پيمان قطعي است و گر نه هر گونه اعتراضي و ادعايي در مورد آن بي تاثير مي باشد . در صورتي كه پيمانكار نسبت به صورت حساب نهايي تهيه شده توسط كارفرما معترض باشد و اعتراض خود را در مهلت تعيين شده اعلام كند و اعتراض او مورد پذيرش كارفرما قرار نگيرد ، پيمانكار مي تواند براي حل مسئله ، طبق ماده 53 اقدام نمايد .
تبصره 1. در صورتي كه به علت تاخير در رسيدگي آخرين صورت وضعيت موقت يا صورت وضعيت قطعي يا تاخير در تهيه صورت حساب نهايي، هزينه هاي اضافي بابت تمديد ضمانت نامه هاي پيمانكار ايجاد شود ، كارفرما اين هزينه هاي اضافي را كه از سوي پيمانكار تامين شده است ، به او پرداخت مي كند و اگر مدت تاخير در آزاد كردن هر يك از تضمينها از 3 ماه بيشتر شود ، كارفرما تضمين مربوط را آزاد مي نمايد .
تبصره 2.هر گاه بر اساس صورت وضعيت قطعي ، معلوم شود كه در آخرين صورت وضعيت موقت ، پيمانكار بدهكار نبوده يا بدهي او كمتر از نصف كسور تضمين حسن انجام كار بوده است يا طبق صورت حساب نهايي ،مشخص شود كه در زمان تصويب صورت وضعيت قطعي پيمانكار بدهكار نبوده است ، كارفرما بايد بي درنگ تضمين آزاد نشده مربوط به هر يك از مدارك ياد شده را آزاد كرده و هزينه تمديد آنها را از سوي پيمانكار تامين شده است ، براي مدتي  كه در آزاد نمودن آنها تاخير ايجاد كرده ، پرداخت كند .', 'این ماده بیان‌کننده نحوه تهیه صورت‌حساب نهایی پیمان پس از پایان عملیات است. بر اساس این حکم، تمامی مطالبات، پرداخت‌ها و تعهدات مالی طرفین باید در صورت‌حساب نهایی جمع‌بندی و بررسی شود. هدف از این مقرره، فراهم کردن مبنای دقیق برای خاتمه مالی پیمان است.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (52, 5, 52, 'تسويه حساب', 'الف) هرگاه بر اساس صورت حساب نهايي كه به شرح ماده 51 تهيه شده است، پيمانكار بستانكار شود، طلب او حداكثر در مدت يك ماه از تاريخ امضاي صورت حساب نهايي يا اعلام كارفرما پرداخت مي گردد و به غير از نصف تضمين حسن انجام كار ، كه تا تحويل قطعي بايد نزد كارفرما باقي بماند ، ديگر تضمين هاي پيمانكار ، از هر نوع كه باشد ، بي درنگ آزاد مي شود.
ب) هر گاه بر اساس صورت حساب نهايي ، پيمانكار بدهكار شود ، مكلف است كه در مدت يك ماه از تاريخ انقضاي صورت حساب نهايي يا اعلام كارفرما ، به شرح بالا طلب كارفرما را بپردازد و اگر از اين پرداخت استنكاف ورزد يا تاخير ورزد ، كارفرما حق دارد ، بدون انجام تشريفات قضايي ، طلب خود را از محل سپرده ها و تضمين هاي پيمانكار (در صورتي كه طبق ماده 47 ضبط نشده باشد ) وصول نمايد و اگر مبالغ اين تضمين ها تكافو ننمايد ، با رعايت قوانين جاري كشور از ديگر داراييهاي او وصل كند .
هرگاه پيمانكار در مهلت مقرر بالا ، طلب كارفرما را پرداخت كند ، به غير از نصف كسور تضمين حسن انجام كار ، كه تا تحويل قطعي نزد كارفرما باقي مي ماند ، بقيه ضمانت نامه ها و سپرده هاي او ، به هر عنوان كه باشد ، بي درنگ آ‍زاد مي شود .', 'این ماده بیان‌کننده فرآیند تسویه حساب نهایی بین کارفرما و پیمانکار است. بر اساس این حکم، پس از انجام تعهدات و تعیین مطالبات، حساب‌های مالی طرفین باید مطابق مقررات پیمان تسویه شود. هدف از این مقرره، پایان دادن رسمی به روابط مالی ناشی از قرارداد است.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (53, 5, 53, 'حل اختلاف', 'الف ) هرگاه در اجرا يا تفسير مفاد پيمان بين دو طرف اختلاف نظر پيش آيد ، دو طرف مي توانند براي حل سريع آن ، قبل از درخواست ارجاع موضوع يا موضوعات مورد اختلاف به داوري طبق بند (ج) بر حسب مورد ، به روش تعيين شده در بند هاي 1 و2 عمل نمايد .
در مورد مسائل ناشي از برداشت متفاوت دو طرف از متون بخش نامه هايي كه به استناد ماده 23 قانون برنامه و بودجه از سوي سازمان برنامه و بودجه ابلاغ شده است ، هر يك از دو طرف از سازمان برنامه و بودجه چگونگي اجراي بخشنامه مربوطه را استعلام نمايد و دو طرف طبق نظري كه از سوي سازمان برنامه و بودجه اعلام مي شود ، عمل كنند .
در مورد اختلاف نظرهايي كه خارج از شمول بند 1 است ،رسيدگي و اعلام نظر دوباره آنها به كارشناس يا هيات كارشناسي منتخب دو طرف واگذار شود و دو طرف طبق نظري كه از سوي كارشناس يا هيات كارشناسي ، در چارچوب پيمان و قوانين و مقررات مربوط اعلام مي گردد ، عمل كنند .
ب) در صورتي كه دو طرف در انتخاب كارشناس يا هيات كارشناسي موضوع بند 2 ، به توافق نرسد يا نظر اعلام شده طبق بند هاي 1 و2 ، مورد قبول هر يك از دو طرف نباشد ، براي حل اختلاف ، طبق بند (ج) اقدام ميگردد .
ج) هرگاه در اجرا يا تفسير مفاد پيمان دو طرف اختلاف نظر پيش آيد ، هريك از طرفها مي تواند درخواست ارجاع موضوع يا موضوعات مورد اختلاف به داوري ره به رئيس سازمان برنامه و بودجه ارائه نمايد .
تبصره 1. چنانچه رئيس سازمان ياد شده با تقاضاي مورد اشاره موافقت نمود ، مرجع حل اختلاف شوراي عالي فني خواهد بود .
تبصره : رسيدگي و اعلام نظر شوراي عالي فني ، در چارچوب پيمان و قوانين و مقررات مربوط انجام مي شود . پس از اعلام نظر شوراي ياد شده ، طرفها بر طبق آن عمل مي نمايند .
د) ارجاع موضوع يا موضوعات مورد اختلاف به شوراي عالي فني ، تغييري در تعهدات قراردادي دو طرف نمي دهد و موجب آن نمي شود كه يكي از دو طرف به تعهدات قراردادي خويش عمل نكند .', 'این ماده بیان‌کننده روش حل اختلافات ناشی از اجرای پیمان است. بر اساس این حکم، طرفین باید اختلافات خود را ابتدا از طریق روش‌های پیش‌بینی‌شده در قرارداد و در صورت لزوم از طریق مراجع قانونی حل‌وفصل نمایند. هدف از این مقرره، جلوگیری از توقف پروژه و تعیین مسیر قانونی رسیدگی به اختلافات است.');
INSERT INTO articles (id, chapter_id, article_number, title, text, interpretation) VALUES (54, 5, 54, 'قوانين و مقررات حاكم بر پيمان', 'قوانين و مقررات حاكم بر پيمان منحصراً قوانين و مقررات كشور جمهوري اسلامي ايران است .', 'این ماده بیان‌کننده قوانین و مقررات حاکم بر پیمان است. بر اساس این حکم، اجرای قرارداد تابع قوانین جاری کشور و مقررات مندرج در اسناد پیمان خواهد بود. هدف از این مقرره، تعیین نظام حقوقی حاکم بر روابط قراردادی طرفین است.');

